   l_col_rows(4)(l_rows) := 'ECC V9: GENERAL LEDGER COMMAND CENTER CONSOLIDATED PATCH';
   l_col_rows(5)(l_rows) := '[2905424.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '35874154';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'ECC V10: GENERAL LEDGER COMMAND CENTER CONSOLIDATED PATCH';
   l_col_rows(5)(l_rows) := '[2947307.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '35302562';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'ECC V11: GENERAL LEDGER COMMAND CENTER CONSOLIDATED PATCH';
   l_col_rows(5)(l_rows) := '[2495053.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '36482187';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'ECC V11 and V12 - AFTER UPGRADING FROM ECC V9 TO V11 GL DASHBOARDS DO NOT RENDER DATA';
   l_col_rows(5)(l_rows) := '[3021035.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '37645372';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'ECC V13 RUP FEBRUARY 2025';
   l_col_rows(5)(l_rows) := '[3074307.1]';

   l_rows := l_rows + 1;
   l_rel_rows(1)(l_rows) := l_rel;
   l_col_rows(1)(l_rows) := '35921604';
   l_col_rows(2)(l_rows) := 'No';
   l_col_rows(3)(l_rows) := NULL;
   l_col_rows(4)(l_rows) := 'FIN CONSOLIDATED PATCH FOR ECC - V12';
   l_col_rows(5)(l_rows) := '[2495053.1]';

END IF;

   l_extra_info('##SHOW_SQL##'):= 'Y';

   l_sig.sigrepo_id := '28501';
   l_sig.title := 'GL ECC Recommended Patches';
   l_sig.fail_condition := '[Applied] = [No]';
   l_sig.problem_descr := 'You have recommended ECC patch(es) that have not been applied to this environment. Please expand the list above for the details to check for any missing latest ECC patches. <br>

 <b>NOTE:</b>  If you have installed the latest version of ECC, you can safely ignore the warning messages related to earlier patch versions.';
   l_sig.solution := 'Above are the recommended patches for the GL ECC product area. For the most current recommendations, use the Patch Wizard or the Updates & Patches Tab in My Oracle Support. Further guidance can be found in the following documents:
<ul>
<li>[11086538] How to Find EBS Patches and EBS Technology Patches</li>
<li>[976188.1] Patch Wizard Utility</li>
<li>[10940175] Patch Wizard FAQ</li>
</ul>
Best Practice:  Always ensure that you are on the latest code with all recommended patches applied. This will help avoid known issues, prevent potential data corruption and provide the latest features and functionality. Having a proactive patching plan and periodic proactive patching process in place are the best ways to stay current.
';
   l_sig.success_msg := '';
   l_sig.print_condition := 'ALWAYS';
   l_sig.fail_type := 'W';
   l_sig.print_sql_output := 'Y';
   l_sig.limit_rows := 'N';
   l_sig.extra_info := l_extra_info;
   l_sig.include_in_xml :='Y';
   l_sig.version := '7';

   -- if snapshot is old, add message to the solution
   IF nvl(g_snap_days, 10) > 30 THEN
       l_sig.solution := l_sig.solution || '<br><br><b>ADADMIN</b>: Maintain Snapshot Information was executed more than 30 days ago.<br>It is recommended that AD Utilities (Adadmin) "Maintain Snapshot Information" is run periodically as key tools (Patch Wizard, ADPatch,etc) rely on this information being accurate and up-to-date.';
   END IF;

  -- Check if applied
  get_current_time(g_query_start_time);
  FOR i in 1..l_rows loop
    l_step := '40';
    OPEN get_app_date(l_col_rows(1)(i),l_rel_rows(1)(i));
    FETCH get_app_date INTO l_app_date;
    CLOSE get_app_date;
    l_col_rows(1)(i) := '{'||l_col_rows(1)(i)||'}';
    IF l_app_date is not null THEN
      l_step := '50';
      l_col_rows(2)(i) := 'Yes';
      l_col_rows(3)(i) := to_char(l_app_date);
    END IF;
  END LOOP;
  g_query_elapsed := stop_timer(g_query_start_time);
  debug(' Rows fetched: '||to_char(l_rows));

  -- Register
  l_step := '60';
  g_signatures('EBS_FIN_ECC_RECOMMENDED_PATCHES') := l_sig;

  --Render
  l_step := '70';
  RETURN process_signature_results(
    'EBS_FIN_ECC_RECOMMENDED_PATCHES',     -- sig ID
    l_sig,                              -- signature information
    l_col_rows,                         -- data
    l_hdr);                             -- headers

EXCEPTION WHEN OTHERS THEN
  print_log('Error in check_rec_patches_2 at step '||l_step);
  raise;
END check_rec_patches_2;




