BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Ledger ID/Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_ledger_id||' - '||l_ledname,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Period Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_period_name,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Budget Version ID/Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(NVL(p_bud_ver_id, -1)||' - '||nvl(l_budname, 'No Budget Selected'),'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Data Collection';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_dc,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Journal Batch Id / Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(NVL(p_batch_id, -1)||' - '||nvl(l_batch_name, 'No Journal Selected'),'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Recurring Journal Batch Id / Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(NVL(p_rec_batch_id, -1)||' - '||nvl(l_rec_batch_name, 'No Recurring Journal Selected'),'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Account ID/Combination';
   g_parameters(g_parameters.LAST).pvalue := mask_text(nvl(p_ccid, -1)||' / '||nvl(l_cciddesc,'No CCID selected'),'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'FSG Report';
   g_parameters(g_parameters.LAST).pvalue := mask_text(nvl(p_rep_id, -1)||' - '||nvl(l_repname, 'No FSG Report Selected '),'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Consolidation ID/Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(NVL(p_consolidation_id, -1)||' - '||nvl(l_consolidation, 'No Consolidation Selected'),'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.41  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2025/12/13 22:14:49 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'gl_hc_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_ledger_id');
IF p_ledger_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Ledger ID/Name is required.');
   raise invalid_parameters;
END IF;
IF p_ledger_id IS NOT NULL THEN
BEGIN
SELECT GLL.LEDGER_ID
INTO l_exists_val
FROM GL_LEDGERS GLL, GL_ACCESS_SET_LEDGERS GASL
WHERE GLL.LEDGER_ID = p_ledger_id
 AND GLL.LEDGER_ID = GASL.LEDGER_ID
AND (
    mo_global.is_mo_init_done = 'N'
    or 
    fnd_profile.value('GL_ACCESS_SET_ID') = GASL.ACCESS_SET_ID
)
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Please enter a Valid Ledger ID.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_ledger_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_ledger_id');

debug('begin parameter validation: p_period_name');
IF p_period_name IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Period Name is required.');
   raise invalid_parameters;
END IF;
IF p_period_name IS NOT NULL THEN
BEGIN
SELECT PERIOD_NAME
INTO l_exists_val
FROM GL_PERIOD_STATUSES
WHERE PERIOD_NAME = p_period_name
 AND application_id = 101
and ledger_id = p_ledger_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Enter the Period Name in the Exact format from your GL Accounting Calendar setup. This parameter value is required.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_period_name failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_period_name');

debug('begin parameter validation: p_bud_ver_id');
IF p_bud_ver_id IS NOT NULL THEN
BEGIN
SELECT NVL(GBV.BUDGET_VERSION_ID, -1)
INTO l_exists_val
FROM GL_BUDGETS GB , GL_BUDGET_VERSIONS GBV
WHERE NVL(GBV.BUDGET_VERSION_ID, -1) = p_bud_ver_id
 AND gbv.budget_name = gb.budget_name
and gb.ledger_id = p_ledger_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Select a Valid Budget specific to the Ledger.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_bud_ver_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_bud_ver_id');

debug('begin parameter validation: p_dc');
IF p_dc IS NOT NULL AND p_dc NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Data Collection response is invalid. Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_dc');

debug('begin parameter validation: p_batch_id');
IF p_batch_id IS NOT NULL THEN
BEGIN
SELECT NVL(B.JE_BATCH_ID, -1)
INTO l_exists_val
FROM GL_JE_BATCHES B, GL_JE_HEADERS H
WHERE NVL(B.JE_BATCH_ID, -1) = p_batch_id
 AND B.JE_BATCH_ID = H.JE_BATCH_ID
AND H.LEDGER_ID = p_ledger_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Please enter a valid Je_batch_id.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_batch_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_batch_id');

debug('begin parameter validation: p_rec_batch_id');
IF p_rec_batch_id IS NOT NULL THEN
BEGIN
SELECT NVL(RECURRING_BATCH_ID,-1)
INTO l_exists_val
FROM GL_RECURRING_BATCHES_V
WHERE NVL(RECURRING_BATCH_ID,-1) = p_rec_batch_id
 AND (ledger_id IS NULL OR ledger_id = p_ledger_id)

 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Please enter a valid RECURRING_BATCH_ID.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_rec_batch_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_rec_batch_id');

debug('begin parameter validation: p_ccid');
IF p_ccid IS NOT NULL THEN
BEGIN
SELECT NVL(GC.CODE_COMBINATION_ID,-1)
INTO l_exists_val
FROM GL_CODE_COMBINATIONS_KFV GC, GL_LEDGERS GLL
WHERE NVL(GC.CODE_COMBINATION_ID,-1) = p_ccid
 AND gc.chart_of_accounts_id = gll.chart_of_accounts_id 
and gll.ledger_id = p_ledger_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Select a Valid Account combination specific to the Ledger.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_ccid failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_ccid');

debug('begin parameter validation: p_rep_id');
IF p_rep_id IS NOT NULL THEN
BEGIN
SELECT NVL(REPORT_ID,-1)
INTO l_exists_val
FROM RG_REPORTS
WHERE NVL(REPORT_ID,-1) = p_rep_id and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Enter a valid FSG Report Name');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_rep_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_rep_id');

debug('begin parameter validation: p_consolidation_id');
IF p_consolidation_id IS NOT NULL THEN
BEGIN
SELECT NVL(GC.CONSOLIDATION_ID, -1)
INTO l_exists_val
FROM GL_CONSOLIDATION GC
WHERE NVL(GC.CONSOLIDATION_ID, -1) = p_consolidation_id and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Enter a Valid Consolidation ID');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_consolidation_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_consolidation_id');


debug('begin parameter validation: p_debug_mode');
IF p_debug_mode IS NOT NULL AND p_debug_mode NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Debug Mode is invalid.  Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_debug_mode');



-- Validation to verify analyzer is run on proper e-Business application version
