-- for FAH integration
BEGIN
g_fah_integration:=true;
l_patch_19795559:=0;
l_source:=0;
begin
 select count(*) into l_patch_19795559
 from ad_bugs
 where bug_number = '19795559';  
 exception
 when others then g_fah_integration:=false;
end;
if l_patch_19795559 > 0 then
  begin
   select count(*) into l_source
   from all_objects 
   where object_name = 'GL_XFR_SOURCE_SYSTEMS'; 
  exception
   when OTHERS then
   g_fah_integration:= false;
  end;

  if l_source>0 then 
   EXECUTE IMMEDIATE 'select count(*) from GL_XFR_SOURCE_SYSTEMS' INTO l_source;
  else 
   g_fah_integration:= false;
  end if; 

else 
 g_fah_integration:= false;
end if;

if l_source > 0 and l_patch_19795559 > 0 then
  g_fah_integration:=true;
  print_log('FAH information available');
else
  g_fah_integration:= false;
  print_log('No FAH information available');
end if;

EXCEPTION   
  when OTHERS then g_fah_integration:= false;
  print_log('Error in gathering FAH information: '||sqlerrm);
END;
