debug('begin add_signature: Misclassified_Accounts');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3123',
      p_sig_id                 => 'Misclassified_Accounts',
      p_sig_sql                => 'SELECT DISTINCT
c.chart_of_accounts_id "Chart of Accounts ID",
c.concatenated_segments "Code Combination",
c.code_combination_id "Code Combination ID",
decode(c.gl_account_type, ''E'', ''Expense'', ''A'', ''Asset'', ''R'', ''Revenue'', ''L'', ''Liability'', ''O'', ''Owners Equity'', c.gl_account_type) "Account Type is",
decode(SUBSTR(v.compiled_value_attributes,5,1), ''E'', ''Expense'', ''A'', ''Asset'', ''R'', ''Revenue'', ''L'', ''Liability'', ''O'', ''Owners Equity'', SUBSTR(v.compiled_value_attributes,5,1)) "Account Type Should be"
FROM
gl_code_combinations_kfv c,
fnd_flex_values v,
fnd_id_flex_segments s,
gl_ledgers b,
fnd_segment_attribute_values fsav,
fnd_segment_attribute_types fsat
WHERE b.ledger_id = ##$$LEDGID$$## and
c.chart_of_accounts_id = s.id_flex_num AND c.template_id IS NULL AND
c.chart_of_accounts_id = b.chart_of_accounts_id AND
s.application_id = 101 AND
s.id_flex_code = ''GL#'' AND
s.flex_value_set_id = v.flex_value_set_id AND
v.flex_value = DECODE (s.application_column_name ,''SEGMENT1'', c.segment1, ''SEGMENT2'', c.segment2 ,''SEGMENT3'', c.segment3 ,''SEGMENT4'', c.segment4 ,''SEGMENT5'', c.segment5 ,''SEGMENT6'', c.segment6 , ''SEGMENT7'', c.segment7 ,''SEGMENT8'', c.segment8 ,''SEGMENT9'', c.segment9 ,''SEGMENT10'', c.segment10 , ''SEGMENT11'', c.segment11 , ''SEGMENT12'', c.segment12 ,''SEGMENT13'', c.segment13 ,''SEGMENT14'', c.segment14 ,''SEGMENT15'', c.segment15 ,''xx'')  AND
c.gl_account_type != SUBSTR(v.compiled_value_attributes,5,1) AND --
s.application_id = fsav.application_id AND
s.id_flex_code = fsav.id_flex_code AND
s.id_flex_num = fsav.id_flex_num AND
s.enabled_flag = ''Y'' AND
s.application_column_name = fsav.application_column_name AND
fsav.application_id = fsat.application_id AND
fsav.id_flex_code = fsat.id_flex_code AND
fsav.attribute_value = ''Y'' AND
fsav.segment_attribute_type = fsat.segment_attribute_type AND
fsat.application_id = 101 AND
fsat.id_flex_code = ''GL#'' AND
fsat.unique_flag = ''Y'' AND
fsat.segment_attribute_type = ''GL_ACCOUNT''  AND
decode(substr(v.compiled_value_attributes,5,1), ''E'', ''Expense'', ''A'', ''Asset'', ''R'', ''Revenue'', ''L'', ''Liability'', ''O'', ''Owners Equity'', substr(v.compiled_value_attributes,5,1))<>''N'' 
AND EXISTS (select ''a'' from gl_balances bal WHERE bal.ledger_id = b.ledger_id)',
      p_title                  => 'Misclassified Accounts',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Misclassified Accounts identified for this ledger.',
      p_solution               => '<ul><li>Please use the following published MOS note to troubleshoot and resolve the Misclassified Accounts.</li>
<li>R12: Troubleshooting Misclassified Accounts in General Ledger [872162.1] </li>
<li>Misclassified Accounts Balance Fix Report to Identify Misclassified Accounts and Correct Corrupted Balances [2377077.1] </li></ul>',
      p_success_msg            => 'No Misclassified accounts identified.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: Misclassified_Accounts');



debug('begin add_signature: RETAINED_EARNINGS_ACCOUNT_TYPE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13830',
      p_sig_id                 => 'RETAINED_EARNINGS_ACCOUNT_TYPE',
      p_sig_sql                => 'SELECT
    gcc.code_combination_id "Retained Earnings CCID",
    gcc.concatenated_segments "Retained Earnings Account",
    DECODE( gcc.gl_account_type,
  ''A'',
  ''Asset'',
  ''L'',
  ''Liability'',
  ''O'',
  ''Ownership/Stockholders Equity'',
  ''E'',
