debug('begin add_signature: Overlapping Child Accounts');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3133',
      p_sig_id                 => 'Overlapping Child Accounts',
      p_sig_sql                => 'SELECT DISTINCT flexset.segment_name "Segment Name",
flexset.segment_num "Segment Number",
fvh1.parent_flex_value "Segment w/Overlapping Children",
 SUBSTR(fvh1.child_flex_value_low,1,30) "Overlapping Child Low Value",
SUBSTR(fvh1.child_flex_value_high,1,30) "Overlapping Child High Value",
SUBSTR(fvh2.child_flex_value_low,1,30) "Overlapped By Child Low Value",
SUBSTR(fvh2.child_flex_value_high,1,30) "Overlapped By Child High Value"
FROM fnd_flex_value_hierarchies fvh1,
fnd_flex_value_hierarchies fvh2,
(SELECT idfs.segment_num,
idfs.flex_value_set_id,
 idfs.application_column_name,
idfs.segment_name
 FROM gl_ledgers glsob,
fnd_id_flex_segments idfs,
fnd_flex_value_sets fvs
 WHERE glsob.chart_of_accounts_id = idfs.id_flex_num
AND fvs.flex_value_set_id = idfs.flex_value_set_id
AND glsob.ledger_id = ##$$LEDGID$$##
AND idfs.application_id = 101
AND idfs.id_flex_code = ''GL#'') flexset
WHERE fvh1.parent_flex_value = fvh2.parent_flex_value
AND fvh1.flex_value_set_id = flexset.flex_value_set_id
AND fvh1.rowid != fvh2.rowid
AND fvh1.flex_value_set_id = fvh2.flex_value_set_id
AND NVL(fvh2.CHILD_FLEX_VALUE_LOW,''X'') <=
NVL(fvh1.CHILD_FLEX_VALUE_HIGH,''X'')
AND NVL(fvh2.CHILD_FLEX_VALUE_HIGH,''X'') >=
NVL(fvh1.CHILD_FLEX_VALUE_LOW,''X'')
ORDER BY flexset.segment_num',
      p_title                  => 'Overlapping Child Accounts',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This section will show if there are any Overlapping Child Accounts exist for the selected ledger.',
      p_solution               => 'Review the results to identify the overlapping child ranges. For further information, refer to [118130.1] and [371580.1].',
      p_success_msg            => 'No Overlapping Child Ranges identified in a Value Set.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: Overlapping Child Accounts');



