debug('begin add_signature: Duplicate GL Code Combinations');
   l_info('##MASK##ORACLE USERNAME'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3138',
      p_sig_id                 => 'Duplicate GL Code Combinations',
      p_sig_sql                => 'SELECT cck.concatenated_segments "Account Combination",
       cck.code_combination_id "Code Combination ID",
       cck.chart_of_accounts_id "Chart of Accounts ID",
       cck.template_id "Summary Template ID",
       cck.last_update_date "Last Updated on",
       ffu.user_name "Oracle Username"
  FROM gl_code_combinations_kfv cck,
       fnd_user ffu
 WHERE ffu.user_id = cck.last_updated_by
   AND (cck.concatenated_segments,
        cck.chart_of_accounts_id,
        NVL(cck.template_id, -99)) IN
     (SELECT cck.concatenated_segments,
             cck.chart_of_accounts_id,
             NVL(cck.template_id, -99)
        FROM gl_code_combinations_kfv cck
        GROUP BY cck.concatenated_segments,
             cck.chart_of_accounts_id,
             NVL(cck.template_id, -99)
      HAVING COUNT(*) >1)
 ORDER BY cck.concatenated_segments,
       cck.last_update_date',
      p_title                  => 'Duplicate GL Code Combinations',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are duplicate rows found in the GL_CODE_COMBINATIONS table.',
      p_solution               => '<ul><li>Please report this issue to Oracle Support Services providing the output of this report. </li>
<li>[1068370.6] GL: Duplicates in GL_CODE_COMBINATIONS Table.</li></ul>',
      p_success_msg            => 'No duplicate rows found in the GL_CODE_COMBINATIONS table.',
