debug('begin add_signature: duplicate_gl_rec_bath_seq');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3442',
      p_sig_id                 => 'duplicate_gl_rec_bath_seq',
      p_sig_sql                => 'select a.last_number "LastSeq GL_RECURRING_BATCHES_S" , 
       b.max_number "Last Seq# GL_RECURRING_BATCHES" 
       from     
          (select last_number from dba_sequences where sequence_name=''GL_RECURRING_BATCHES_S'') a,
          (select max(RECURRING_BATCH_ID) max_number from GL_RECURRING_BATCHES) b
where a.last_number < b.max_number',
      p_title                  => 'GL_RECURRING_BATCHES_S Sequence',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Please check GL_RECURRING_BATCHES_S database sequence exist in the database. If yes, then review the following:',
      p_solution               => '<ul><li>The GL_RECURRING_BATCHES_S sequence will attempt to create a duplicate RECURRING_BATCH_ID record the next time it is executed.</li>
<li>Please log this issue with Oracle Support Services providing the output of this report.</li></ul>',
      p_success_msg            => 'GL_RECURRING_BATCHES_S sequence is valid because the last sequence number used in GL_RECURRING_BATCHES is less than the last number of the sequence.',
