debug('begin add_signature: PC SubLedger Details - Period Statuses');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3446',
      p_sig_id                 => 'PC SubLedger Details - Period Statuses',
      p_sig_sql                => 'SELECT
    ps_gl.ledger_id         "Ledger ID",
    ps_gl.period_name       "Period",
    apps.application_name   "Application Name",
    DECODE(ps.closing_status, ''N'', ''Never Opened'', ''O'', ''Open'', ''C'', ''Closed'', ''F'', ''Future Entry'', ''P'', ''Permanently Closed'', ps
    .closing_status) "Subledger Period Status",
    DECODE(ps_gl.closing_status, ''N'', ''Never Opened'', ''O'', ''Open'', ''C'', ''Closed'', ''F'', ''Future Entry'', ''P'', ''Permanently Closed'',
    ps_gl.closing_status) "GL Period Status"
FROM
    gl_period_statuses ps_gl,
    fnd_application_vl apps,
    gl_period_statuses ps
WHERE
    ps_gl.application_id != ps.application_id
    AND apps.application_id = ps.application_id
    AND ps_gl.ledger_id = ps.ledger_id
    AND ps_gl.period_name = ps.period_name
    AND ps_gl.application_id = 101
    AND ps.application_id IN (
        SELECT
            i.application_id
        FROM
            fnd_product_installations i
        WHERE
            i.application_id IN (
                140,
                200,
                222,
                201,
                275
            )
            AND i.status IN (
                ''I'',
                ''S''
            )
    )
    AND ps_gl.period_name = ''##$$PERNAME$$##'' 
    AND ps_gl.ledger_id = ##$$LEDGID$$##
    AND ps.closing_status NOT IN (
        ''P'',
        ''C'',
        ''N''
    )',
      p_title                  => 'SubLedger Details - Period Statuses',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<ul><li>Subledger period statuses tested for applications Assets, Payables, Projects, Receivables, Purchasing.</li>
<li>Not all subledger periods are closed for this General Ledger period.</li>
<li>Reconciliations of subledger control accounts cannot be relied upon until the subledger period is closed.</li></ul>',
      p_solution               => 'Please ensure that the above subledger periods are closed before closing the General Ledger period for the selected ledger.',
      p_success_msg            => '<ul><li>Subledger period statuses tested for applications Assets, Payables, Projects, Receivables, Purchasing.</li>
<li>Subledger periods are status closed, permanently closed or never opened for these subledgers that are in use for this General Ledger period.</li></ul>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: PC SubLedger Details - Period Statuses');



debug('begin add_signature: PC_ACTUAL_INCORRECT_BALANCES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3447',
      p_sig_id                 => 'PC_ACTUAL_INCORRECT_BALANCES',
      p_sig_sql                => 'SELECT Init_per.ccid
 , Init_per.bal_currency_code "Currency Code"
 , Init_per.period_name "Previous Period Name"
 , Init_per.Clsng_Dr_Bal "Closing Debit Balance"
 , Init_per.Clsng_Cr_Bal "Closing Credit Balance"
 , Foll_per.period_name "Current Period Name"
 , Foll_per.Opening_Dr_Bal "Opening Debit Balance"
 , Foll_per.Opening_Cr_Bal "Opening Credit Balance"
 ,decode(Init_per.gl_account_type, ''O'', ''Ownership/Stockholders Equity'', ''A'', ''Asset'', ''E'', ''Expense'', ''R'', ''Revenue'', ''L'', ''Liability'', Init_per.gl_account_type) "Account Type"
 FROM (
 SELECT bal.code_combination_id ccid
 , bal.currency_code bal_currency_code
 , bal.period_name
 ,gcc.gl_account_type
 , sum(bal.period_net_dr + bal.begin_balance_dr) Clsng_Dr_Bal  , sum(bal.period_net_cr + bal.begin_balance_cr) Clsng_Cr_Bal  FROM gl_balances bal, gl_code_combinations_kfv gcc  WHERE bal.ledger_id = 1  and bal.code_combination_id = gcc.code_combination_id  AND bal.period_name =  (SELECT PrePeriod.PERIOD_NAME
                        FROM GL_PERIOD_STATUSES PrePeriod
                        WHERE PrePeriod.APPLICATION_ID = 101
                        AND PrePeriod.LEDGER_ID = 1
                        AND PrePeriod.EFFECTIVE_PERIOD_NUM =
                              (SELECT MAX(EFFECTIVE_PERIOD_NUM)
                                FROM GL_PERIOD_STATUSES P1
                                WHERE P1.APPLICATION_ID = 101
                                AND P1.LEDGER_ID = ##$$LEDGID$$##
                                AND P1.EFFECTIVE_PERIOD_NUM <
                                      (SELECT EFFECTIVE_PERIOD_NUM
                                        FROM GL_PERIOD_STATUSES P2
                                        WHERE P2.APPLICATION_ID = 101
                                        AND P2.LEDGER_ID = ##$$LEDGID$$##
                                        AND P2.PERIOD_NAME = ''##$$PERNAME$$##'')))  AND bal.actual_flag = ''A''
 AND bal.template_id is null
 AND decode(bal.translated_flag, null,''R'',bal.translated_flag) = ''R''
 GROUP BY bal.code_combination_id, bal.currency_code, bal.period_name, gcc.gl_account_type  ORDER BY bal.code_combination_id, bal.currency_code
 ) Init_per
 , (
 SELECT bal.code_combination_id ccid
 , bal.currency_code bal_currency_code
 , bal.period_name
 , gcc.gl_account_type
 , sum(bal.begin_balance_dr) Opening_Dr_Bal  , sum(bal.begin_balance_cr) Opening_Cr_Bal  FROM gl_balances bal,  gl_code_combinations_kfv gcc  WHERE bal.ledger_id = 1  and bal.code_combination_id = gcc.code_combination_id  AND bal.period_name = ''##$$PERNAME$$##''
 AND bal.actual_flag = ''A''
 AND bal.template_id is null
 AND decode(bal.translated_flag, null,''R'',bal.translated_flag) = ''R''
 GROUP BY bal.code_combination_id, bal.currency_code, bal.period_name, gcc.gl_account_type  ORDER BY bal.code_combination_id, bal.currency_code
 ) Foll_per
 WHERE foll_per.ccid = init_per.ccid
 AND foll_per.bal_currency_code = Init_per.bal_currency_code  AND (foll_per.Opening_Dr_Bal != Init_per.Clsng_Dr_Bal  OR foll_per.Opening_Cr_Bal != Init_per.Clsng_Cr_Bal)  ORDER BY Init_per.bal_currency_code, Init_per.ccid',
      p_title                  => 'Actuals Ending Balance  Prior Period to Beginning Balance Current Period',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Actual Prior Period Closing Balances <> This Period Beginning Balances.<br>
<b>NOTE: </b> Differences  are natural (and not necessarily an error) when comparing the Last Period of one year with the First Period of the next year for Expense  and Revenue account types, and Retained Earnings Account defined for the  Ledger.',
      p_solution               => '<ul><li>Please ensure that you follow all the suggested steps in the following MOS Note to resolve the balances issue. </li>
<li> [2745665.1] R12: GLBALFIX Auto Installation Script and Concurrent Program "General Ledger - Automated Balance Fix" to Rectify Balance Corruptions. </li></li>
<li> [11137202] GLBALFIX: GL Balances Corruption Datafix - Primary Note. </li></ul>',
      p_success_msg            => 'Actuals for Prior Period closing balances = this period beginning balances.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '12'
      );
   l_info.delete;
debug('end add_signature: PC_ACTUAL_INCORRECT_BALANCES');



debug('begin add_signature: PC_ENCUMBRANCE_INCORRECT_BALANCES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3448',
      p_sig_id                 => 'PC_ENCUMBRANCE_INCORRECT_BALANCES',
      p_sig_sql                => 'SELECT  Init_per.ccid 
      ,      Init_per.bal_currency_code "Currency Code" 
      ,      Init_per.period_name "Previous Period Name" 
      ,      Init_per.Clsng_Dr_Bal "Closing Debit Balance" 
      ,      Init_per.Clsng_Cr_Bal "Closing Credit Balance" 
      ,      Foll_per.period_name "Current Period Name" 
      ,      Foll_per.Opening_Dr_Bal "Opening Debit Balance" 
      ,      Foll_per.Opening_Cr_Bal "Opening Credit Balance" 
      FROM   (  
             SELECT bal.code_combination_id ccid 
             ,       bal.currency_code bal_currency_code 
             ,       bal.period_name 
             ,       sum(bal.period_net_dr + bal.begin_balance_dr) Clsng_Dr_Bal 
             ,       sum(bal.period_net_cr + bal.begin_balance_cr) Clsng_Cr_Bal 
             FROM    gl_balances bal 
             WHERE   bal.ledger_id = ##$$LEDGID$$##
             AND     bal.period_name =  (SELECT PrePeriod.PERIOD_NAME
                        FROM GL_PERIOD_STATUSES PrePeriod
                        WHERE PrePeriod.APPLICATION_ID = 101
                        AND PrePeriod.LEDGER_ID = ##$$LEDGID$$##
                        AND PrePeriod.EFFECTIVE_PERIOD_NUM =
                              (SELECT MAX(EFFECTIVE_PERIOD_NUM)
                                FROM GL_PERIOD_STATUSES P1
                                WHERE P1.APPLICATION_ID = 101
                                AND P1.LEDGER_ID = ##$$LEDGID$$##
                                AND P1.EFFECTIVE_PERIOD_NUM <
                                      (SELECT EFFECTIVE_PERIOD_NUM
                                        FROM GL_PERIOD_STATUSES P2
                                        WHERE P2.APPLICATION_ID = 101
                                        AND P2.LEDGER_ID = ##$$LEDGID$$##
                                        AND P2.PERIOD_NAME = ''##$$PERNAME$$##'')))
             AND     bal.actual_flag = ''E'' 
             AND     bal.template_id is null 
             AND     decode(bal.translated_flag, null,''R'',bal.translated_flag) = ''R'' 
             GROUP BY bal.code_combination_id, bal.currency_code, bal.period_name 
             ORDER BY bal.code_combination_id, bal.currency_code 
             )  Init_per 
      ,      (  
             SELECT bal.code_combination_id ccid 
             ,       bal.currency_code bal_currency_code 
             ,       bal.period_name 
             ,       sum(bal.begin_balance_dr) Opening_Dr_Bal 
             ,       sum(bal.begin_balance_cr) Opening_Cr_Bal 
             FROM    gl_balances bal 
             WHERE   bal.ledger_id = ##$$LEDGID$$##
             AND     bal.period_name = ''##$$PERNAME$$##''
             AND     bal.actual_flag = ''E'' 
             AND     bal.template_id is null 
             AND     decode(bal.translated_flag, null,''R'',bal.translated_flag) = ''R'' 
             GROUP BY bal.code_combination_id, bal.currency_code, bal.period_name 
             ORDER BY bal.code_combination_id, bal.currency_code 
             ) Foll_per 
      WHERE  foll_per.ccid = init_per.ccid 
      AND    foll_per.bal_currency_code = Init_per.bal_currency_code 
      AND    (foll_per.Opening_Dr_Bal != Init_per.Clsng_Dr_Bal 
      OR     foll_per.Opening_Cr_Bal != Init_per.Clsng_Cr_Bal) 
      ORDER BY Init_per.bal_currency_code, Init_per.ccid',
      p_title                  => 'Encumbrance Ending Balance Prior Period to Begin Balance Current Period',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Encumbrance Prior period closing balances <> this period beginning balances. ',
      p_solution               => 'You can ignore this warning if you did not do Carry Forward Encumbrances for some Encumbrance Types of the first period for the new Fiscal Year.  Otherwise, please report this issue to Oracle Support Services providing the output of this report.',
      p_success_msg            => 'Encumbrances Prior Period closing balances = this period beginning balances.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: PC_ENCUMBRANCE_INCORRECT_BALANCES');



debug('begin add_signature: PC Journal Import');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3375',
      p_sig_id                 => 'PC Journal Import',
      p_sig_sql                => 'SELECT DECODE(gli.actual_flag,''A'',''Actual'',''E'', ''Encumbrance'',''Error'') "Balance Type"
        ,                         gli.user_je_source_name "Source Name"
        ,          gli.user_je_category_name "Category Name",
        gli.status "Import Status",
        gli.group_id "Group Id",
        to_char(gli.accounting_date, ''DD-MON-YYYY'') "Accounting Date",
        count(*) "Number of Records"
        FROM    GL_INTERFACE gli
        ,       GL_PERIOD_STATUSES ps   
        WHERE   gli.ledger_id = ps.ledger_id  
        AND     ps.application_id = 101  
        AND     gli.accounting_date < (ps.end_date+1) 
        AND     gli.actual_flag in(''A'',''E'') 
        AND     upper(gli.status) != ''PROCESSED'' 
        AND     gli.ledger_id = ##$$LEDGID$$##
        AND     ps.period_name = ''##$$PERNAME$$##'' 
        GROUP BY gli.actual_flag,gli.user_je_source_name, 
        gli.user_je_category_name,gli.status, 
        gli.ledger_id ,  gli.group_id ,gli.accounting_date',
      p_title                  => 'Journal Import',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are Journal entries awaiting import, Before closing period.',
      p_solution               => '<ul><li>There are Journal entries awaiting import,.Before closing period, It is recommended that all non-interfaced journal entries are imported into General Ledger for this period and prior periods.</li>

<li>It is also recommended for performance reasons to periodically ensure that the General Ledger interface table GL_INTERFACE) is low on volume of records.</li>

<li>Refer [130542.1] General Ledger: Journal Import Process.</li>

<li>Also, review Oracle General Ledger User Guide, Chapter: Journal Entry, Section: How to Import Journals to know how to run Journal import program manually.</li></ul>
<br />
Click <a href="http://www.oracle.com/technetwork/documentation/applications-167706.html" target="_blank">here</a> to go to Oracle Applications Documentation webpage.',
      p_success_msg            => 'There are no Journal entries awaiting import, before closing period.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: PC Journal Import');



debug('begin add_signature: PC_PROCESSED_JOURNAL_IMPORT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3538',
      p_sig_id                 => 'PC_PROCESSED_JOURNAL_IMPORT',
      p_sig_sql                => 'select distinct ledger_id "Ledger ID",
