debug('begin add_signature: PC Journal Posting');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3376',
      p_sig_id                 => 'PC Journal Posting',
      p_sig_sql                => 'SELECT  jb.name "Batch Name"
        ,          jb.je_batch_id "Batch Id"
        ,          jb.default_period_name "Batch Period"
        ,          jb.actual_flag
--        ,          lookupBatch.meaning "Batch Status"
--        ,          lookupApprove.meaning "Approval Status Code"
,(SELECT lookupBatch.meaning
FROM   apps.gl_lookups lookupBatch
WHERE  1=1
AND    lookupBatch.lookup_type = ''BATCH_STATUS''
AND jb.status = lookupBatch.lookup_code
)   "Batch Status"
,(SELECT lookupApprove.meaning
FROM   apps.gl_lookups lookupApprove
WHERE  1=1
AND    lookupApprove.lookup_type = ''JE_BATCH_APPROVAL_STATUS''
AND jb.approval_status_code = lookupApprove.lookup_code
)   "Approval Status Code"
        ,          jh.name "Journal Header Name"
        ,          jh.period_name "Journal Header Period"
        ,          decode(jh.status,''U'',''Unposted'',''P'',''Posted'',jh.status) "Journal Header Status"
        FROM     gl_je_batches jb,gl_je_headers jh, gl_lookups lookupBatch 
        ,        gl_lookups lookupApprove 
        WHERE    jb.je_batch_id = jh.je_batch_id 
        AND      jh.ledger_id = ##$$LEDGID$$##
        AND      lookupBatch.lookup_type = ''BATCH_STATUS'' 
        AND      jb.status = lookupBatch.lookup_code 
        AND      lookupApprove.lookup_type = ''JE_BATCH_APPROVAL_STATUS'' 
        AND      jb.approval_status_code = lookupApprove.lookup_code 
        AND      (jb.default_effective_date <= (select end_date from gl_period_statuses where application_id = 101 and ledger_id = ##$$LEDGID$$## and period_name = ''##$$PERNAME$$##'' )
        OR     jh.default_effective_date <= (select end_date from gl_period_statuses where application_id = 101 and ledger_id = ##$$LEDGID$$## and period_name = ''##$$PERNAME$$##'' ))
        AND      (jb.status != ''P'' 
        OR jh.status != ''P'')
        ORDER BY jb.default_effective_date desc',
      p_title                  => 'Journal Posting',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are Journal entries awaiting Posting, Before closing period.',
      p_solution               => '<ul><li>There are Journals which have yet to be posted.</li>
<li>Please review them and use Journal Post program to post the required journals before attempting to close this period.</li></ul>',
      p_success_msg            => 'All the journals for this Ledger are Posted.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: PC Journal Posting');



