debug('begin add_signature: PC Actual Dr - Cr Beginning Balances');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3384',
      p_sig_id                 => 'PC Actual Dr - Cr Beginning Balances',
      p_sig_sql                => 'select  bal.currency_code Currency,
           SUM(bal.begin_balance_dr) Debits,
           SUM(bal.begin_balance_cr) Credits,
           SUM(bal.begin_balance_dr) - SUM(bal.begin_balance_cr) Difference
    FROM    gl_balances bal 
    WHERE   bal.ledger_id = ##$$LEDGID$$##
    AND     bal.period_name = ''##$$PERNAME$$##''
    AND     bal.actual_flag = ''A'' 
    AND     bal.currency_code != ''STAT'' 
    AND     bal.template_id IS NULL 
    AND     decode(bal.translated_flag, null,''R'',bal.translated_flag) = ''R'' 
    GROUP BY bal.currency_code 
    HAVING  SUM(bal.begin_balance_dr) - SUM(bal.begin_balance_cr) != 0',
      p_title                  => 'Actual Dr/Cr Beginning Balances',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Actual begin debit balances <> begin credit balances. The beginning balances do not match.',
      p_solution               => '<ul><li>Please ensure that you follow all the suggested steps in the following MOS Note to resolve the balances issue. </li>
