  add_signature(
      p_sig_repo_id            => '11345',
      p_sig_id                 => 'GL_JE_DIFF_PERIOD',
      p_sig_sql                => 'SELECT DISTINCT gll.ledger_id "Ledger ID", 
gll.name "Ledger Name",
jb.je_batch_id "Batch ID",
