debug('begin add_signature: GL_JE_DIFF_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11346',
      p_sig_id                 => 'GL_JE_DIFF_STATUS',
      p_sig_sql                => 'SELECT jeb.je_batch_id ,
  jeb.name b_name,
  jel.je_header_id,
  jeh.name h_name,
  jeb.status b_status,
