debug('begin add_signature: LINES_VERSUS_BALANCES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10470',
      p_sig_id                 => 'LINES_VERSUS_BALANCES',
      p_sig_sql                => 'SELECT
T.code_combination_id code_combination_id,
T.concatenated_segments concatenated_segments,
T.period_name period_name,
T.currency_code currency_code,
SUM(NVL(T.BALANCES_CR, 0)) BALANCES_CR,
SUM(NVL(T.balances_dr, 0)) balances_dr,
SUM(NVL(T.lines_cr, 0)) lines_cr,
SUM(NVL(T.lines_dr, 0)) lines_dr
FROM
(SELECT led.ledger_id,
l.code_combination_id code_combination_id,
cc.concatenated_segments concatenated_segments,
h.period_name period_name,
led.currency_code currency_code,
0 BALANCES_CR,
0 balances_dr,
SUM(NVL(l.accounted_cr, 0)) lines_cr,
SUM(NVL(l.accounted_dr, 0)) lines_dr
FROM gl.gl_je_headers h ,
gl.gl_je_lines l ,
GL_CODE_COMBINATIONS_KFV CC ,
GL_LEDGERS LED
WHERE h.period_name = ''##$$PERNAME$$##''
AND l.code_combination_id = CC.CODE_COMBINATION_ID
AND h.ledger_id =led.ledger_id
AND h.je_header_id = l.je_header_id
AND h.currency_code != ''STAT''
AND l.STATUS = ''P''
AND h.actual_flag=''A''
AND led.ledger_id =  ##$$LEDGID$$##
GROUP BY led.ledger_id,
l.code_combination_id,
cc.concatenated_segments,
h.period_name,
led.currency_code
UNION ALL
SELECT led.ledger_id,
b.code_combination_id code_combination_id,
cc.concatenated_segments concatenated_segments,
b.period_name period_name,
b.currency_code currency_code,
NVL(B.PERIOD_NET_CR, 0) BALANCES_CR,
NVL(b.period_net_dr, 0) balances_dr,
0 lines_cr,
0 lines_dr
FROM GL.GL_BALANCES B,
GL_CODE_COMBINATIONS_KFV CC ,
GL_LEDGERS LED
WHERE b.ledger_id = led.ledger_id
AND b.actual_flag = ''A''
AND b.currency_code != ''STAT''
AND b.currency_code = led.CURRENCY_CODE
AND b.translated_flag IS NULL
AND b.template_id IS NULL
AND CC.CODE_COMBINATION_ID =B.CODE_COMBINATION_ID
AND led.ledger_id = ##$$LEDGID$$##
AND b.period_name = ''##$$PERNAME$$##''
AND (NVL(B.PERIOD_NET_CR, 0) <>0
OR NVL(B.PERIOD_NET_DR, 0) <>0)
) T
GROUP BY T.code_combination_id,
T.concatenated_segments,
T.period_name ,
T.currency_code
HAVING SUM(NVL(T.balances_cr,0)) <> SUM(NVL(T.lines_cr,0))
OR SUM(NVL(T.balances_dr,0)) <> SUM(NVL(T.lines_dr,0))',
      p_title                  => 'Lines versus Balances',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Posted journals do not match balances',
      p_solution               => '<ul><li>Please ensure that you follow all the suggested steps in the following MOS Note to resolve the balances issue. </li>
<li> [2745665.1] R12: GLBALFIX Auto Installation Script and Concurrent Program "General Ledger - Automated Balance Fix" to Rectify Balance Corruptions. </li></li>
<li> [11137202] GLBALFIX: GL Balances Corruption Datafix - Primary Note. </li></ul>',
      p_success_msg            => 'Posted journals match balances.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: LINES_VERSUS_BALANCES');



debug('begin add_signature: Calendar Overlapping Periods or Gaps');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3394',
      p_sig_id                 => 'Calendar Overlapping Periods or Gaps',
      p_sig_sql                => 'SELECT  perset1.period_set_name "Accounting Calendar Name"
      , pt.user_period_type "Period Type" 
      , perset1.period_name "Period Name"
      , perset1.end_date "End Date" 
      , perset2.period_name "Next Period Name"
      , perset2.start_date "Start Date" 
      , decode(sign(perset2.start_date - perset1.end_date - 1) 
               ,-1,''OVERLAP'',1,''GAP'',0,null) "Problem" 
FROM    (SELECT rownum rn
        ,       period_name 
        ,       period_set_name 
        ,       start_date, end_date, period_type
        FROM    (SELECT per.period_name 
                ,       per.period_set_name 
                ,       per.period_type 
                ,       per.start_date 
                ,       per.end_date 
                FROM    GL_LEDGERS ledger 
                ,       GL_PERIODS per 
                WHERE   ledger.period_set_name = per.period_set_name 
                AND     per.adjustment_period_flag = ''N'' 
                AND     ledger.ledger_id = ##$$LEDGID$$##
                order by per.period_type, per.start_date) 
        ) perset1, 
       (SELECT rownum rn
        ,       period_name 
        ,       period_set_name 
        ,       start_date 
        ,       end_date
        ,       period_type 
        FROM    (SELECT per.period_name
                ,       per.period_set_name
                ,       per.period_type 
                ,       per.start_date 
                ,       per.end_date 
                FROM    GL_LEDGERS ledger 
                ,       GL_PERIODS per 
                WHERE   ledger.period_set_name = per.period_set_name 
                AND     per.adjustment_period_flag = ''N'' 
                AND     ledger.ledger_id = ##$$LEDGID$$## 
                order by per.period_type, per.start_date) ) perset2, 
       GL_PERIOD_TYPES pt
WHERE   perset2.rn = perset1.rn + 1
AND     perset2.start_date != perset1.end_date + 1
AND     perset2.period_type = perset1.period_type 
AND     perset2.period_type = pt.period_type',
      p_title                  => 'Calendar Overlapping Periods or Gaps',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<b>ALERT! </b> Overlapping periods or gaps between periods have been detected.',
      p_solution               => '<ul><li>Please fix the problems identified in this section as soon as possible. Run the General Ledger concurrent program "Other - Calendar Validation Report" for more information.</li>
<li> [1061798.1] R12: Calendar Changes that can be Supported in General Ledger. 
<li> [95447.1] Calendar Missing Date - Gap Datafix 
</li></ul>',
      p_success_msg            => 'No overlapping periods or gaps in periods found for this Ledger.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: Calendar Overlapping Periods or Gaps');



