debug('begin add_signature: EBS_FIN_GL_ECC_PROGRAMS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '28493',
      p_sig_id                 => 'EBS_FIN_GL_ECC_PROGRAMS',
      p_sig_sql                => 'select * from (SELECT DISTINCT fcr.REQUEST_ID, fcpt.user_concurrent_program_name Program,
              fcr.argument_text AS Parameters,
              DECODE(
      fcr.PHASE_CODE,
      ''C'', ''Completed'',
      ''I'', ''Inactive'',
      ''P'', ''Pending'',
      ''R'', ''Running'',
      fcr.PHASE_CODE
    ) AS Phase,
    DECODE(
      fcr.STATUS_CODE,
      ''A'', ''Waiting'',
      ''B'', ''Resuming'',
      ''C'', ''Normal'',
      ''D'', ''Cancelled'',
      ''E'', ''Error'',
      ''F'', ''Scheduled'',
      ''G'', ''Warning'',
      ''H'', ''On Hold'',
      ''I'', ''Normal'',
      ''M'', ''No Manager'',
      ''Q'', ''Standby'',
      ''R'', ''Normal'',
      ''S'', ''Suspended'',
      ''T'', ''Terminating'',
      ''U'', ''Disabled'',
      ''W'', ''Paused'',
      ''X'', ''Terminated'',
      ''Z'', ''Waiting'',
      fcr.STATUS_CODE
    ) AS Status,
       fcrs.completion_text,
       TO_CHAR(fcr.ACTUAL_START_DATE, ''dd-mm-yy hh24:mi:ss'') AS Start_Time,
       TO_CHAR(fcr.ACTUAL_COMPLETION_DATE, ''dd-mm-yy hh24:mi:ss'') AS End_Time,
       fu.user_id
FROM fnd_concurrent_requests fcr,
     fnd_concurrent_programs fcp,
     fnd_concurrent_programs_tl fcpt,
     fnd_conc_req_summary_v fcrs,
     fnd_user fu     
WHERE fcr.CONCURRENT_PROGRAM_ID = fcp.CONCURRENT_PROGRAM_ID
  AND fcr.actual_start_date >= (SYSDATE - 14)
  AND (
      (fcpt.user_concurrent_program_name = ''ECC Run Data Load'' AND fcr.argument_text LIKE ''%EBS,%'' AND fcr.argument_text LIKE ''%gl,%'')
      OR
      (fcpt.user_concurrent_program_name = ''General Ledger Command Center Data Load'')
    )
  AND fcr.PROGRAM_APPLICATION_ID = fcp.APPLICATION_ID
  AND fcpt.concurrent_program_id = fcr.concurrent_program_id
  AND fcr.REQUESTED_BY = fu.user_id
  AND fcrs.request_id = fcr.request_id
  ORDER BY fcr.REQUEST_ID desc)
 where rownum <= 12',
      p_title                  => 'GL ECC Concurrent Program Run Details',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The "General Ledger Command Center Data Load" and its "ECC Run Data Load" concurrent programs submitted in Last 14 Days with a max count of 12 records.
',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_GL_ECC_PROGRAMS');



