  add_signature(
      p_sig_repo_id            => '28498',
      p_sig_id                 => 'EBS_FIN_GL_ECC_ACCESS_ROLE_ASSIGNMENTS',
      p_sig_sql                => 'SELECT
    wr.name         AS "Role Name",
    wr.display_name AS "Role Display Name",
    wr.description  AS "Role Description",
    decode( wra.USER_NAME, NULL, NVL(wra.USER_NAME, ''No User Assigned''), (decode(LENgth(wra.user_name), 0, NULL,SUBSTR(wra.user_name,1,LENgth(wra.user_name)-3)) || ''**'' )) user_name, 
    wra.role_name,
    wra.relationship_id,
    wra.assigning_role,
    wra.start_date,
    wra.end_date,
    wra.created_by,
    wra.creation_date,
    wra.last_updated_by,
    wra.last_update_date,
    wra.last_update_login,
    wra.user_start_date,
    wra.role_start_date,
    wra.assigning_role_start_date,
    wra.user_end_date,
    wra.role_end_date,
    wra.assigning_role_end_date,
    wra.partition_id,
    wra.effective_start_date,
    wra.effective_end_date,
    wra.user_orig_system,
    wra.user_orig_system_id,
    wra.role_orig_system,
    wra.role_orig_system_id,
    wra.parent_orig_system,
    wra.parent_orig_system_id,
    wra.owner_tag,
    wra.assignment_reason
FROM
    wf_roles                 wr
    LEFT JOIN wf_user_role_assignments wra ON wr.name = wra.role_name
WHERE
    upper(wr.name) LIKE upper(''%GL_ECC_ACCESS_ROLE%'')
ORDER BY
    wra.user_name,
    wr.name',
      p_title                  => 'GL_ECC_ACCESS Roles And Assignments',
