      p_success_msg            => 'GL Program - Optimizer program has been ran in last 30 days.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: GL_CHECK_WHEN_OPTIMIZER_HAS_BEEN_RUN');



debug('begin add_signature: FC Gather Statistics');
   l_info('##SHOW_SQL##'):= 'Y';
