debug('begin add_signature: gl_bc_period_map_B_ROws');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3666',
      p_sig_id                 => 'gl_bc_period_map_B_ROws',
      p_sig_sql                => 'select ''No B Rows in gl_bc_period_map Table'' "Budget Rows", 
count(*) "Row Count"
 from gl_period_statuses glp,
 gl_budgets glb,
 gl_budget_versions glbv
 where glbv.budget_version_id = NVL(''##$$BUDVERID$$##'', -1)
 and glb.budget_name = glbv.budget_name
 and glp.ledger_id = ##$$LEDGID$$##
 and glp.application_id = 101
 and glp.period_year <= nvl(glb.latest_opened_year,0)
 and glp.period_num >= (select min(glbpr.start_period_num) from
 gl_budget_period_ranges glbpr
 where glbpr.budget_version_id = NVL(''##$$BUDVERID$$##'', -1)
 and glbpr.period_year = glp.period_year)
 and glp.period_num <= (select max(glbpr.end_period_num) from
 gl_budget_period_ranges glbpr
 where glbpr.budget_version_id = NVL(''##$$BUDVERID$$##'', -1)
 and glbpr.period_year = glp.period_year)
 and not exists (select ''1'' from gl_bc_period_map glpm
 where glpm.ledger_id = ##$$LEDGID$$##
 and glpm.actual_flag = ''B''
 and glpm.budget_version_id = NVL(''##$$BUDVERID$$##'', -1)
 and glpm.boundary_code = ''P''
 and glpm.transaction_period_name = glp.period_name
 )
 group by ''No B Rows in gl_bc_period_map Table''',
      p_title                  => 'Missing Budget Rows In GL_BC_PERIOD_MAP Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Missing Budget rows in gl_bc_period_map Table',
      p_solution               => 'Please use [1115496.1] to resolve the Missing ''B'' rows in gl_bc_period_map Table.',
      p_success_msg            => 'There are no Missing Budget rows in GL_BC_PERIOD_MAP Table.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: gl_bc_period_map_B_ROws');



debug('begin add_signature: gl_bc_period_map_S_Rows');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3665',
      p_sig_id                 => 'gl_bc_period_map_S_Rows',
      p_sig_sql                => 'SELECT distinct ''No S Rows exists in gl_bc_period_map Table'' "S Rows in gl_bc_period_map"
   FROM gl_period_statuses gps2,
        gl_period_statuses gps1
  WHERE gps1.ledger_id = ##$$LEDGID$$##
    and gps1.application_id = 101
    and gps1.closing_status != ''N''
    and gps2.ledger_id = ##$$LEDGID$$##
    and gps2.application_id = 101
    and gps2.period_year = gps1.period_year
    and gps2.period_num  =
        (
          SELECT min( gps.period_num )
            FROM gl_period_statuses gps
           WHERE gps.ledger_id = ##$$LEDGID$$##
             and gps.application_id = 101
             and gps.period_year = gps2.period_year
        )
        and not exists
        (
          SELECT ''1''
            FROM gl_bc_period_map gbpm
           WHERE gbpm.ledger_id = ##$$LEDGID$$##
             and gbpm.actual_flag = ''A''
             and gbpm.boundary_code = ''S''
             and gbpm.transaction_period_name = gps1.period_name
        )',
      p_title                  => 'Missing S Rows In GL_BC_PERIOD_MAP Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Missing S rows in gl_bc_period_map Table',
      p_solution               => 'Please use [1115496.1] to resolve the Missing S rows in gl_bc_period_map Table.',
      p_success_msg            => 'There are No Missing S rows in GL_BC_PERIOD_MAP Table',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: gl_bc_period_map_S_Rows');



