debug('begin add_signature: FC_PLSQL_FILE_VERSIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3473',
      p_sig_id                 => 'FC_PLSQL_FILE_VERSIONS',
      p_sig_sql                => 'select o.object_name,
       substr(ltrim(rtrim(substr(substr(s.text, instr(s.text,''Header: '')),
                                    instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 1),
                                    instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 2) -
                                    instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 1) ))), 1, 25) "File Name",
       substr(ltrim(rtrim(substr(substr(s.text, instr(s.text,''Header: '')),
                                    instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 2),
                                    instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 3) -
                                    instr(substr(s.text, instr(s.text,''Header: '')), '' '', 1, 2) ))), 1, 30) "File version",
      decode(o.object_type, ''PACKAGE'' , ''SPEC'', ''PACKAGE BODY'', ''BODY'') type,
      o.object_type pkg_type,
      o.status status
from  user_objects o , user_source s
where s.name = o.object_name
and   s.type = o.object_type
and   o.object_type  in (''PACKAGE'' , ''PACKAGE BODY'')
and   (o.object_name like ''##$$FK2$$##\_%'' escape ''\'') 
and   s.line between 2 and 3
and   s.text like ''%Header: %''
order by 1, 3 desc, 5 desc',
      p_title                  => 'PLSQL File Versions',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Package versions',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: FC_PLSQL_FILE_VERSIONS');



debug('begin add_signature: FC_OTHER_FILE_VERSIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5491',
      p_sig_id                 => 'FC_OTHER_FILE_VERSIONS',
      p_sig_sql                => 'select que.subdir,que.filename, que.version
from (
select files.filename filename,files.subdir subdir,
file_version.version version,
rank()over(partition by files.filename
order by file_version.version_segment1 desc,
file_version.version_segment2 desc,file_version.version_segment3 desc,
file_version.version_segment4 desc,file_version.version_segment5 desc,
file_version.version_segment6 desc,file_version.version_segment7 desc,
file_version.version_segment8 desc,file_version.version_segment9 desc,
file_version.version_segment10 desc,
file_version.translation_level desc) as rank1
from ad_file_versions file_version,
(
select filename, app_short_name, subdir, file_id
from ad_files af, fnd_application fa
where af.app_short_name = fa.application_short_name
and fa.application_id = ##$$FK1$$##
and af.subdir not like ''admin%''
and af.subdir not like ''help%''
and af.subdir not like ''%driver%''
and af.subdir not like ''%readme%''
and substr(af.subdir, instr(af.subdir, ''/'', -1)+1) not in (select language_code
 from fnd_languages
 where installed_flag <> ''B'')
and af.filename not like ''%.txt''
and af.filename not like ''%.a''
and af.filename not like ''%.gif''
and af.filename not like ''%.htm''
and af.filename not like ''%.html''
) files
where files.file_id = file_version.file_id
) que
where rank1 = 1
order by 1,2',
      p_title                  => 'Other File Versions',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Could not find other file versions',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: FC_OTHER_FILE_VERSIONS');



