      p_sig_sql                => 'SELECT
    ledgeroptioneo.transfer_to_gl_mode_code,
    ledgeroptioneo.acct_reversal_option_code,
    decode(ledgeroptioneo.capture_event_flag, ''Y'', ''N'', ''Y'') AS use_primary_ledger_amt_flag,
    ledgeroptioneo.capture_event_flag,
    ledgeroptioneo.enabled_flag,
    launchoptioneo.application_id,
    launchoptioneo.ledger_id,
    launchoptioneo.accounting_mode_code,
    launchoptioneo.accounting_mode_override_flag,
    launchoptioneo.summary_report_flag,
    launchoptioneo.summary_report_override_flag,
    launchoptioneo.submit_transfer_to_gl_flag,
    launchoptioneo.submit_transfer_override_flag,
    launchoptioneo.submit_gl_post_flag,
    launchoptioneo.submit_gl_post_override_flag,
    decode(launchoptioneo.error_limit, NULL, ''N'', ''Y'') AS stop_on_error_flag,
    launchoptioneo.error_limit,
    launchoptioneo.processes,
    launchoptioneo.processing_unit_size,
    ledgeroptioneo.rounding_rule_code,
    ledgeroptioneo.merge_acct_option_code,
    sublgr.control_account_type_code
FROM
    xla_ledger_options   ledgeroptioneo,
    xla_launch_options   launchoptioneo,
    xla_subledgers       sublgr
WHERE
    ( ( ledgeroptioneo.application_id = launchoptioneo.application_id (+) )
      AND ( ledgeroptioneo.ledger_id = launchoptioneo.ledger_id (+) )
      AND ( ledgeroptioneo.application_id = sublgr.application_id ) )
      AND ( ledgeroptioneo.ledger_id = ##$$LEDGID$$## )',
      p_title                  => 'Subledger Accounting Options Setup',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This provides the Accounting Options Setup definition details for the selected Ledger.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: ACCOUNTING_OPTIONS_SUMMARY');



