debug('begin add_signature: DC_LEDGER_DEFINITION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6137',
      p_sig_id                 => 'DC_LEDGER_DEFINITION',
      p_sig_sql                => 'select ''Ledger Name = '' || NAME || '' (ID = ''|| ledger_id || '')'' "LEDGER DEFINITION" from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Short Name = '' || short_name from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Description = '' || description from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Currency = '' || currency_code from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Ledger Type = '' || initcap(ledger_category_code) from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Chart of Accounts = '' || NAME || '' (ID = ''|| chart_of_accounts_id || '')'' from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Accounting Calendar = '' || period_set_name  "ACCOUNTING CALENDAR" from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Period Type = '' || accounted_period_type from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''First Ever Opened Period = '' || first_ledger_period_name from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select  ''Latest GL Opened Period = '' || LATEST_OPENED_PERIOD_NAME from gl_ledgers WHERE ledger_id = ##$$LEDGID$$##
union all
select ''Number of Future Enterable Periods = '' || future_enterable_periods_limit from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Subledger Accounting Method = '' || SLA_ACCOUNTING_METHOD_CODE from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Use Cash Basis Accounting = '' || sla_ledger_cash_basis_flag from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Retained Earnings Account = '' || gcc.concatenated_segments ||''(''|| gll.ret_earn_code_combination_id||'')''  from gl_ledgers gll, gl_code_combinations_kfv gcc where gll.ret_earn_code_combination_id = gcc.code_combination_id
and ledger_id = ##$$LEDGID$$##
union all
select ''Rounding Differences Tracking Account = '' || gcc.concatenated_segments ||''(''|| gll.rounding_code_combination_id||'')''  from gl_ledgers gll, gl_code_combinations_kfv gcc where gll.rounding_code_combination_id = gcc.code_combination_id
and ledger_id = ##$$LEDGID$$##
union all
select ''Cumulative Translation Adjustment Account = '' || gcc.concatenated_segments ||''(''|| gll.cum_trans_code_combination_id||'')''  from gl_ledgers gll, gl_code_combinations_kfv gcc where gll.cum_trans_code_combination_id = gcc.code_combination_id
and ledger_id = ##$$LEDGID$$##
union all
select Distinct ''Suspense Account = '' || gcc.concatenated_segments ||''(''|| gsa.code_combination_id||'')''  from GL_SUSPENSE_ACCOUNTS gsa, gl_code_combinations_kfv gcc where gsa.code_combination_id = gcc.code_combination_id
and gsa.ledger_id = ##$$LEDGID$$##
union all
select ''Enable Average Balances = '' || enable_average_balances_flag from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Budgetary Control Enabled = '' || enable_budgetary_control_flag from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Journal Approval Enabled = '' || enable_je_approval_flag from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Enable Journal Reconciliation = '' || enable_reconciliation_flag from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Enable Secondary Track Flag = '' || enable_secondary_track_flag from gl_ledgers where ledger_id = ##$$LEDGID$$##
union all
select ''Period End Rate Type = '' || User_conversion_type from GL_DAILY_CONVERSION_TYPES where conversion_type IN (select distinct PERIOD_END_RATE_TYPE from gl_ledgers where ledger_id = ##$$LEDGID$$##)
union all
select ''Average Rate Type = '' || User_conversion_type from GL_DAILY_CONVERSION_TYPES where conversion_type IN (select distinct PERIOD_AVERAGE_RATE_TYPE from gl_ledgers where ledger_id = ##$$LEDGID$$##)',
      p_title                  => 'Ledger Definition',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This provides the Ledger Setup definition details for the selected Ledger.',
      p_solution               => 'Not a Valid Ledger',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: DC_LEDGER_DEFINITION');



debug('begin add_signature: DC_CHART_OF_ACCOUNTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6129',
      p_sig_id                 => 'DC_CHART_OF_ACCOUNTS',
      p_sig_sql                => 'select distinct fifst.id_flex_structure_name|| ''(''  || gll.chart_of_accounts_id ||'')'' "Chart of Accounts Name/ID"
 , gll.name|| ''(''  || gll.ledger_id ||'')'' "Ledger Name/ID"
, decode(fifs.enabled_flag, ''Y'', ''Yes'', ''N'', ''No'', fifs.enabled_flag) "COA Enabled"
, decode(fifs.cross_segment_validation_flag, ''Y'', ''Yes'', ''N'', ''No'', fifs.cross_segment_validation_flag) "COA Cross Validation Enabled"
, decode(fifs.freeze_flex_definition_flag, ''Y'', ''Yes'', ''N'', ''No'', fifs.freeze_flex_definition_flag) "COA Frozen"
, decode(fifs.dynamic_inserts_allowed_flag, ''Y'', ''Yes'', ''N'', ''No'', fifs.dynamic_inserts_allowed_flag) "COA Dynamic Inserts Allowed"
, ifs.segment_name "Segment Name"
, decode(ifs.enabled_flag, ''Y'', ''Yes'', ''N'', ''No'', ifs.enabled_flag) "Segment Enabled"
, decode(ifs.required_flag, ''Y'', ''Yes'', ''N'', ''No'', ifs.required_flag) "Segment Required"
, decode(ifs.display_flag, ''Y'', ''Yes'', ''N'', ''No'', ifs.display_flag) "Segment Displayed"
, ifs.application_column_name "Appl Column Name"
, ffvs.flex_value_set_name|| '' (''  || ffvs.flex_value_set_id ||'')'' "FF Value Set Name/ID"
, Decode(ffvs.validation_type, ''F'', ''Table'',
''I'', ''Independent'', 
''D'', ''Dependent'', 
''N'', ''None'',
''P'', ''Pair'', 
''U'', ''Special'', 
''X'', ''Translatable Independent'', 
''Y'', ''Translatable Dependent'',
ffvs.validation_type) "Value Set Validation Type"
, decode(fsav1.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav1.attribute_value) "Balancing Segment"
, decode(fsav2.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav2.attribute_value ) "Cost Center Segment"
, decode(fsav3.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav3.attribute_value ) "Natural Account Segment"
, decode(fsav4.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav4.attribute_value ) "Intercompany Segment"
, decode(fsav5.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav5.attribute_value) "Secondary Tracking Segment"
, decode(fsav6.attribute_value, ''Y'', ''Yes'', ''N'', ''No'', fsav6.attribute_value ) "Management Segment"
from fnd_id_flex_structures fifs
, fnd_id_flex_structures_tl fifst
, fnd_id_flex_segments ifs
, fnd_flex_value_sets ffvs
, gl_ledgers gll
, fnd_segment_attribute_values fsav1
, fnd_segment_attribute_values fsav2
, fnd_segment_attribute_values fsav3
, fnd_segment_attribute_values fsav4
, fnd_segment_attribute_values fsav5
, fnd_segment_attribute_values fsav6
where 1=1
and fifs.id_flex_code = ''GL#''
and fifs.application_id = fifst.application_id
and fifs.id_flex_code = fifst.id_flex_code
and fifs.id_flex_num = fifst.id_flex_num
and fifs.application_id = ifs.application_id
and fifs.id_flex_code = ifs.id_flex_code
and fifs.id_flex_num = ifs.id_flex_num
and fsav1.application_id = ifs.application_id
and fsav1.id_flex_code = ifs.id_flex_code
and fsav1.id_flex_num = ifs.id_flex_num
and fsav1.application_column_name = ifs.application_column_name
and fsav2.application_id = ifs.application_id
and fsav2.id_flex_code = ifs.id_flex_code
and fsav2.id_flex_num = ifs.id_flex_num
and fsav2.application_column_name = ifs.application_column_name
and fsav3.application_id = ifs.application_id
and fsav3.id_flex_code = ifs.id_flex_code
and fsav3.id_flex_num = ifs.id_flex_num
and fsav3.application_column_name = ifs.application_column_name
and fsav4.application_id = ifs.application_id
and fsav4.id_flex_code = ifs.id_flex_code
and fsav4.id_flex_num = ifs.id_flex_num
and fsav4.application_column_name = ifs.application_column_name
and fsav5.application_id = ifs.application_id
and fsav5.id_flex_code = ifs.id_flex_code
and fsav5.id_flex_num = ifs.id_flex_num
and fsav5.application_column_name = ifs.application_column_name
and fsav6.application_id = ifs.application_id
and fsav6.id_flex_code = ifs.id_flex_code
and fsav6.id_flex_num = ifs.id_flex_num
and fsav6.application_column_name = ifs.application_column_name
and fsav1.segment_attribute_type = ''GL_BALANCING''
and fsav2.segment_attribute_type = ''FA_COST_CTR''
and fsav3.segment_attribute_type = ''GL_ACCOUNT''
and fsav4.segment_attribute_type = ''GL_INTERCOMPANY''
and fsav5.segment_attribute_type = ''GL_SECONDARY_TRACKING''
and fsav6.segment_attribute_type = ''GL_MANAGEMENT''
and ifs.id_flex_num = gll.chart_of_accounts_id
and ifs.flex_value_set_id = ffvs.flex_value_set_id
and gll.ledger_id = ##$$LEDGID$$##
order by ifs.application_column_name',
      p_title                  => 'Chart of Accounts Definition',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This provides the Chart of Accounts definition for the selected Ledger.',
      p_solution               => 'No Chart of Accounts exists. Please select a valid Ledger Name.',
      p_success_msg            => 'This provides the Chart of Accounts definition for the selected Ledger.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: DC_CHART_OF_ACCOUNTS');



