      p_sig_repo_id            => '6130',
      p_sig_id                 => 'DC_CROSS_VALIDATION_RULES',
      p_sig_sql                => 'SELECT DISTINCT
    ffvr.application_id "##$$FK1$$##",
    ffvr.id_flex_code "##$$FK2$$##",
    ffvrtl.flex_validation_rule_name "##$$FK3$$##",
    ffvr.id_flex_num "##$$FK4$$##",
    ffvrtl.flex_validation_rule_name   "CVR Name",
    fifs.id_flex_structure_name        "Chart of Accounts",
    DECODE(ffvr.enabled_flag, ''Y'', ''Yes'', ''N'', ''No'', ffvr.enabled_flag) "Enabled",
    ffvr.error_segment_column_name     "Error Segment",
    ffvrtl.error_message_text          "Error Message",
    ffvrtl.creation_date
FROM
    gl_ledgers gll,
    fnd_flex_validation_rules ffvr,
    fnd_flex_vdation_rules_tl ffvrtl,
    fnd_id_flex_structures_vl fifs,
    fnd_id_flex_segments_vl fifsv,
    fnd_id_flexs fif
WHERE
    ffvr.application_id = ffvrtl.application_id
    AND fifs.id_flex_num = ffvr.id_flex_num
    AND ffvr.id_flex_code = ffvrtl.id_flex_code
    AND ffvr.id_flex_num = ffvrtl.id_flex_num
    AND ffvr.flex_validation_rule_name = ffvrtl.flex_validation_rule_name
    AND ffvr.application_id = 101
    AND fif.id_flex_name = ''Accounting Flexfield''
    AND fifsv.id_flex_code = fif.id_flex_code
    AND fifs.id_flex_code = fif.id_flex_code
    AND gll.ledger_id = ##$$LEDGID$$##
    AND gll.chart_of_accounts_id = fifs.id_flex_num
ORDER BY
    ffvrtl.flex_validation_rule_name,
    fifs.id_flex_structure_name',
      p_title                  => 'Cross Validation Rules',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This provides the Cross Validation Rules defined for General Ledger application.',
      p_solution               => 'No Validation Rules defined for General Ledger application.',
      p_success_msg            => 'This provides the Cross Validation Rules defined for General Ledger application.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('CROSS_VALIDATION_RULE_RANGES'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: DC_CROSS_VALIDATION_RULES');



debug('begin add_signature: DC_SECURITY_RULES_DEFINITION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6127',
      p_sig_id                 => 'DC_SECURITY_RULES_DEFINITION',
      p_sig_sql                => 'select distinct rule.flex_value_rule_name		"Security Rule Name",
        fifs.segment_name	"Segment Name"			   						,
        rule.parent_flex_value_low	"Parent Value LOW"				,
        rule.parent_flex_value_high	"Parent Value HIGH"			,
        decode(rulelin.include_exclude_indicator, ''E'', ''Exclude'', ''I'', ''Include'', rulelin.include_exclude_indicator) "Type"			,
        rulelin.flex_value_low		"From"	   						,
        rulelin.flex_value_high		"TO"	,
        ffvs.flex_value_set_name				"Value Set Name"		 		,
        rule.description "Description"        
from gl_ledgers gll,
fnd_flex_value_rules_vl rule, 
fnd_flex_value_sets ffvs, 
fnd_flex_value_rule_lines rulelin, 
fnd_id_flex_segments fifs, 
fnd_application_tl fatl
where rule.flex_value_set_id = ffvs.flex_value_set_id
and rule.flex_value_rule_id = rulelin.flex_value_rule_id(+)
and fifs.flex_value_set_id = ffvs.flex_value_set_id
and fifs.application_id = fatl.application_id
and fifs.application_id = 101
and gll.chart_of_accounts_id = fifs.id_flex_num
and gll.ledger_id = ##$$LEDGID$$##
order by 
fifs.segment_name, 
ffvs.flex_value_set_name,
rule.flex_value_rule_name,
rule.parent_flex_value_low,
rule.parent_flex_value_high,
rulelin.flex_value_low, 
rulelin.flex_value_high',
      p_title                  => 'Security Rules Definition',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This provides the Security Rules defined for your General Ledger Application.',
      p_solution               => 'No Security Rules defined for General Ledger.',
      p_success_msg            => 'This provides the Security Rules defined for your General Ledger Application.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: DC_SECURITY_RULES_DEFINITION');



debug('begin add_signature: DC_SECURITY_RULES_ASSIGNED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6128',
      p_sig_id                 => 'DC_SECURITY_RULES_ASSIGNED',
      p_sig_sql                => 'SELECT rule.flex_value_rule_name|| ''(''  || rule.flex_value_rule_id ||'')''  "Security Rule Name/ID"
