WHERE  rule.flex_value_rule_id = usage.flex_value_rule_id 
AND    rule.flex_value_set_id = usage.flex_value_set_id 
AND    usage.responsibility_id = resp.responsibility_id 
AND    rule.flex_value_set_id = segs.flex_value_set_id 
AND    usage.application_id = segs.application_id 
AND    segs.application_id = 101 
AND    segs.id_flex_code = ''GL#'' 
AND    segs.id_flex_num = GLL.CHART_OF_ACCOUNTS_ID
