      p_sig_sql                => 'SELECT distinct postSet.autopost_set_name "AutoPost Criteria Set"
,      postSet.description "Description"
,      postSet.enabled_flag "Enabled"
,      postSet.submit_all_priorities_flag "Submit All Priorities"
