,      postSet.effective_days_after "Journal Effective Dates To"
,      postOpt.posting_priority "Priority"
,      case when je_source_name=''ALL'' THEN (SELECT ''ALL'' from dual) else ( select source.user_je_source_name from GL_JE_SOURCES_TL source where source.je_source_name = postOpt.je_source_name and source.language=''US'' ) end  "Source"
,      case when je_category_name=''ALL'' THEN (SELECT ''ALL'' from dual) else ( select cat.user_je_category_name from GL_JE_CATEGORIES_TL cat where cat.je_category_name = postOpt.je_category_name  and cat.language=''US'' ) end  "Category"
