debug('begin add_signature: EBS_FIN_FC_BUDGET_LAST_PERIOD');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24729',
      p_sig_id                 => 'EBS_FIN_FC_BUDGET_LAST_PERIOD',
      p_sig_sql                => 'SELECT
    gb.budget_name,
    gb.budget_version_id,
    gb.show_status,
    gb.require_budget_journals_flag,
    gb.first_valid_period_name,
    gb.last_valid_period_name,
    gb.ledger_name
FROM
    gl_budgets_v gb
WHERE
        gb.budget_version_id = nvl(''##$$BUDVERID$$##'',- 1 ) 
    AND status IN ( ''O'',
                    ''C'' )
    AND gb.last_valid_period_num <> (
        SELECT
            MAX(gp.period_num)
        FROM
            gl_ledgers gll,
            gl_periods gp
        WHERE
                gll.accounted_period_type = gp.period_type
            AND gll.ledger_id = nvl(''##$$LEDGID$$##'', - 1) )',
      p_title                  => 'Budget Setup - Last Period Name',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The last period of the budget definition is not the same as the last period of the year in the calendar.',
      p_solution               => '<ul><li>Please use the following published MOS note to resolve the issue.</li>
<li>GLXBDDEF: Changing The Last Budget Period Throws Error FRM-40200 Field is protected against update [213650.1] </li>
<li>	GLXBDDEF Why Is the Open Next Year Button Greyed Out on the Define Budget Form ? [118335.1] </li></ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_FC_BUDGET_LAST_PERIOD');



debug('begin add_signature: DC_BUDGET_DEFINITION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6131',
      p_sig_id                 => 'DC_BUDGET_DEFINITION',
      p_sig_sql                => 'SELECT budget.budget_name "Budget Name"
,      budget.description "Description"
,      decode(budget.status,''O'',''Open'',''F'',''Frozen'', ''C'', ''Current'', budget.status) "Status"
,      decode(budget.require_budget_journals_flag, ''N'', ''No'', ''Y'', ''Yes'', budget.require_budget_journals_flag) "Require Budget Journals Flag"
,      budget.date_created "Created"
,      budget.date_closed "Frozen"
,      budget.first_valid_period_name "First"
,      budget.last_valid_period_name "Last"
,      budget.latest_opened_year "Latest Open Year"
,      budget.budget_type "Budget Type"
FROM   GL_BUDGETS budget 
WHERE  budget.ledger_id = ##$$LEDGID$$## 
 order by 
      case 
        when budget.status = ''C'' then 1 
        when budget.status = ''O'' then 2 
        else 3
      end,
  budget.budget_name asc',
