debug('begin add_signature: DC_BUDGET_ORG_ASSIGNMENT_RANGES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6133',
      p_sig_id                 => 'DC_BUDGET_ORG_ASSIGNMENT_RANGES',
      p_sig_sql                => 'SELECT
    range.budget_entity_id   "Budget Entity Id",
    range.range_id           "Range Id",
    NVL(range.range_id, -1)  "##$$FK2$$##",
    range.sequence_number    "Line",
    DECODE(range.entry_code, ''E'', ''Entered'', ''C'', ''Calculated'', range.entry_code) "Type",
    range.currency_code      "Currency",
    range.status             "Status",
    rtrim(ltrim(range.segment1_low
                || ''-''
                || range.segment2_low
                || ''-''
                || range.segment3_low
                || ''-''
                || range.segment4_low
                || ''-''
                || range.segment5_low
                || ''-''
                || range.segment6_low
                || ''-''
                || range.segment7_low
                || ''-''
                || range.segment8_low
                || ''-''
                || range.segment9_low
                || ''-''
                || range.segment10_low, ''-''), ''-'') "From",
    rtrim(ltrim(range.segment1_high
                || ''-''
                || range.segment2_high
                || ''-''
                || range.segment3_high
                || ''-''
                || range.segment4_high
                || ''-''
                || range.segment5_high
                || ''-''
                || range.segment6_high
                || ''-''
                || range.segment7_high
                || ''-''
                || range.segment8_high
                || ''-''
                || range.segment9_high
                || ''-''
                || range.segment10_high, ''-''), ''-'') "TO"
FROM
    gl_budget_assignment_ranges_v range,
    gl_budget_entities org
WHERE
    org.ledger_id = range.ledger_id
    AND org.budget_entity_id = range.budget_entity_id
        AND range.ledger_id = ##$$LEDGID$$##
AND org.budget_entity_id = NVL(##$$FK1$$##, -1)
AND nvl(org.start_date, SYSDATE) <= SYSDATE
    AND nvl(org.end_date, SYSDATE) >= SYSDATE
        AND org.status_code = ''C''
ORDER BY org.budget_entity_id,
                                           range.sequence_number',
      p_title                  => 'Budget Organization Assignment Ranges',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This provides the Budget Organization assignments for the selected ledger. It selects the segments from first 10 segments values of Account from and To with a "-" segment separator.',
      p_solution               => 'No Budget Organization assignments for the selected ledger.',
      p_success_msg            => '',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('BUD_ORG_CONTROL_OPTIONS'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: DC_BUDGET_ORG_ASSIGNMENT_RANGES');



