      p_sig_repo_id            => '2421',
      p_sig_id                 => 'GL Ledger Relationships Information',
      p_sig_sql                => 'SELECT 
    glr.relationship_id,
    glr.source_ledger_id,
    pl.name AS "Primary Ledger",
    glr.target_ledger_id,
    tl.name AS "Target Ledger",
    glr.sla_ledger_id,
    glr.primary_ledger_id,
    glr.target_currency_code,
