    glr.gl_je_conversion_set_id,
    glr.sl_coa_mapping_id,
    glr.automatic_post_flag,
    glr.alc_default_conv_rate_type,
    glr.alc_no_rate_action_code,
    glr.alc_max_days_roll_rate,
    glr.alc_inherit_conversion_type,
