      p_sig_sql                => 'SELECT distinct O.BUSINESS_GROUP_ID ,
       O.ORGANIZATION_ID ,
    OTL.NAME ,
    O.DATE_FROM ,
    O.DATE_TO ,
    O3.ORG_INFORMATION5 SHORT_CODE,
    O3.ORG_INFORMATION3 Ledger_id ,
    O3.ORG_INFORMATION2 DEFAULT_LEGAL_CONTEXT_ID,
