debug('begin add_signature: COA_ROLLUP_RULES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13815',
      p_sig_id                 => 'COA_ROLLUP_RULES',
      p_sig_sql                => 'SELECT
    a.to_segment_name            "Target Segment",
    a.single_value               "Target Segment Detail Value",
    a.segment_map_type_display   "Transfer Level Using",
    a.parent_rollup_value        "Source Segment Parent Value",
    a.child_flex_value_low       "Source Segment Ranges Low",
    a.child_flex_value_high      "Source Segment Ranges High",
    a.mapping_id,
    a.segment_map_id,
    a.segment_map_type
FROM (
        ( SELECT
    mapv.row_id                         row_id,
    mapv.segment_map_id                 segment_map_id,
    mapv.coa_mapping_id                 mapping_id,
    mapv.last_update_date               last_update_date,
    mapv.last_updated_by                last_updated_by,
    mapv.to_value_set_id                to_value_set_id,
    mapv.to_application_column_name     to_application_column_name,
    ffs1.segment_name                   to_segment_name,
    ffs1.segment_num                    to_segment_num,
    mapv.segment_map_type               segment_map_type,
    l.meaning                           segment_map_type_display,
    mapv.creation_date                  creation_date,
    mapv.created_by                     created_by,
    mapv.last_update_login              last_update_login,
    mapv.from_value_set_id              from_value_set_id,
    mapv.from_application_column_name   from_application_column_name,
    ffs2.segment_name                   from_segment_name,
    ffs2.segment_num                    from_segment_num,
    mapv.single_value                   single_value,
    mapv.attribute1                     attribute1,
    mapv.attribute2                     attribute2,
    mapv.attribute3                     attribute3,
    mapv.attribute4                     attribute4,
    mapv.attribute5                     attribute5,
    mapv.context                        context,
    mapv.parent_rollup_value            parent_rollup_value,
    fvs.validation_type                 validation_type,
    gcrrv.child_flex_value_low,
    gcrrv.child_flex_value_high
FROM
    gl_lookups l,
    fnd_id_flex_segments ffs1,
    fnd_id_flex_segments ffs2,
    fnd_flex_value_sets fvs,
    gl_segment_map_cons_v mapv,
    gl_cons_rollup_ranges_v gcrrv
WHERE
    ffs1.application_id = 101
    AND ffs1.id_flex_code = ''GL#''
    AND ffs1.id_flex_num = mapv.to_chart_of_accounts_id
    AND ffs1.application_column_name = mapv.to_application_column_name
    AND ffs2.application_id (+) = 101
    AND ffs2.id_flex_code (+) = ''GL#''
    AND ffs2.id_flex_num (+) = mapv.from_chart_of_accounts_id
    AND ffs2.application_column_name (+) = mapv.from_application_column_name
    AND l.lookup_type = ''SEGMENT_MAP_TYPE''
    AND l.lookup_code = mapv.segment_map_type
    AND fvs.flex_value_set_id = mapv.to_value_set_id
    AND ffs1.segment_name = ''##$$FK3$$##''
    AND gcrrv.segment_map_id(+) = mapv.segment_map_id
    AND gcrrv.segment_map_type(+) = mapv.segment_map_type
    AND mapv.segment_map_type <> ''P''
        AND mapv.coa_mapping_id = ##$$FK2$$##
            AND l.meaning IN (
                ''Detail Rollup Ranges'',
                ''Parent Value'',
                ''Detail Rollup Via Parent''
            )
        )
        UNION ALL
        ( SELECT
            mapv.row_id                         row_id,
            mapv.segment_map_id                 segment_map_id,
            mapv.coa_mapping_id                 mapping_id,
            mapv.last_update_date               last_update_date,
            mapv.last_updated_by                last_updated_by,
            mapv.to_value_set_id                to_value_set_id,
            mapv.to_application_column_name     to_application_column_name,
            ffs1.segment_name                   to_segment_name,
            ffs1.segment_num                    to_segment_num,
            mapv.segment_map_type               segment_map_type,
            l.meaning                           segment_map_type_display,
            mapv.creation_date                  creation_date,
            mapv.created_by                     created_by,
            mapv.last_update_login              last_update_login,
            mapv.from_value_set_id              from_value_set_id,
            mapv.from_application_column_name   from_application_column_name,
            ffs2.segment_name                   from_segment_name,
            ffs2.segment_num                    from_segment_num,
            mapv.single_value                   single_value,
            mapv.attribute1                     attribute1,
            mapv.attribute2                     attribute2,
            mapv.attribute3                     attribute3,
            mapv.attribute4                     attribute4,
            mapv.attribute5                     attribute5,
            mapv.context                        context,
            mapv.parent_rollup_value            parent_rollup_value,
            fvs.validation_type                 validation_type,
            gcrrv.child_flex_value_low,
            gcrrv.child_flex_value_high
        FROM
            gl_lookups l,
            fnd_id_flex_segments ffs1,
            fnd_id_flex_segments ffs2,
            fnd_flex_value_sets fvs,
            gl_segment_map_cons_v mapv,
            gl_cons_rollup_ranges_v gcrrv
        WHERE
            ffs1.application_id = 101
            AND ffs1.id_flex_code = ''GL#''
            AND ffs1.id_flex_num = mapv.to_chart_of_accounts_id
            AND ffs1.application_column_name = mapv.to_application_column_name
            AND ffs2.application_id (+) = 101
            AND ffs2.id_flex_code (+) = ''GL#''
            AND ffs2.id_flex_num (+) = mapv.from_chart_of_accounts_id
            AND ffs2.application_column_name (+) = mapv.from_application_column_name
            AND l.lookup_type = ''SEGMENT_MAP_TYPE''
            AND l.lookup_code = mapv.segment_map_type
            AND fvs.flex_value_set_id = mapv.to_value_set_id
            AND mapv.coa_mapping_id = ##$$FK2$$##
            AND ffs1.segment_name = ''##$$FK3$$##''
            AND gcrrv.flex_value_set_id = ##$$FK4$$## AND gcrrv.parent_flex_value = mapv.parent_rollup_value )
    ) a
ORDER BY
    a.single_value,
    a.child_flex_value_low,
    a.child_flex_value_high',
      p_title                  => 'Rollup Rules',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Chart of Accounts Mapping Segment/Rollup Rules with Source Segment Ranges.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: COA_ROLLUP_RULES');



debug('begin add_signature: COA_SEGMENT_RULES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13814',
      p_sig_id                 => 'COA_SEGMENT_RULES',
      p_sig_sql                => 'SELECT DISTINCT
    NVL(a.from_value_set_id, -1) "##$$FK4$$##"
    , to_segment_num    "Seg#"
    , to_segment_name   "Target Segment"
    , to_segment_name "##$$FK3$$##"
    , DECODE(segment_map_type, ''C'', ''Copy Value From'', ''S'', ''Assign Single Value'', ''R'', ''Use Rollup Rules From'', ''N'', ''Not Assigned''
    , segment_map_type) "Action"
    , DECODE(from_segment_name, NULL, single_value, from_segment_name) "Source Segment"
    , mapping_id "##$$FK2$$##"
FROM
    gl_cons_segment_map_v a
WHERE
    mapping_id = ##$$FK1$$##
    AND a.segment_map_type IN (
        ''C'',
        ''R'',
        ''S'',
        ''U''
    )
ORDER BY
    a.to_segment_num',
      p_title                  => 'Segment Rules',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Chart of Accounts Mapping Segment Rules.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('COA_ROLLUP_RULES'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
