debug('begin add_signature: COA_MAPPING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13813',
      p_sig_id                 => 'COA_MAPPING',
      p_sig_sql                => 'SELECT
    a.mapping_id                    mapping_id,
    a.mapping_id                    "##$$FK1$$##",
    a.mapping_name                  "COA Mapping",
    a.to_chart_of_accounts_name     "COA Target",
    a.from_chart_of_accounts_name   "COA Source",
    a.start_date_active             "Start Date",
    a.end_date_active               "End Date",
    DECODE(a.security_flag, ''N'', ''No'', ''Y'', ''Yes'', a.security_flag) "Security Enabled"
FROM
    (
        SELECT
            map.rowid                         row_id,
            map.coa_mapping_id                mapping_id,
            map.name                          mapping_name,
            map.last_update_date              last_update_date,
            map.last_updated_by               last_updated_by,
            from_coa.id_flex_structure_name   from_chart_of_accounts_name,
            from_coa.id_flex_num              from_chart_of_accounts_id,
            to_coa.id_flex_structure_name     to_chart_of_accounts_name,
            to_coa.id_flex_num                to_chart_of_accounts_id,
            map.creation_date                 creation_date,
            map.created_by                    created_by,
            map.last_update_login             last_update_login,
            map.description                   description,
            map.start_date_active             start_date_active,
            map.end_date_active               end_date_active,
            map.security_flag                 security_flag,
            DECODE(map.security_flag, ''Y'', DECODE(fnd_data_security.check_function(1.0, ''GL_DAS_COA_MAPPING_V'', ''GL_DAS_COA_MAPPING''
            , TO_CHAR(map.coa_mapping_id), NULL, NULL, NULL, NULL, fnd_global.user_name), ''T'', ''Y'', ''N''), ''Y'') view_privilege,
            DECODE(map.security_flag, ''Y'', DECODE(fnd_data_security.check_function(1.0, ''GL_DAS_COA_MAPPING_U'', ''GL_DAS_COA_MAPPING''
            , TO_CHAR(map.coa_mapping_id), NULL, NULL, NULL, NULL, fnd_global.user_name), ''T'', ''Y'', ''N''), ''Y'') use_privilege,
            DECODE(map.security_flag, ''Y'', DECODE(fnd_data_security.check_function(1.0, ''GL_DAS_COA_MAPPING_M'', ''GL_DAS_COA_MAPPING''
            , TO_CHAR(map.coa_mapping_id), NULL, NULL, NULL, NULL, fnd_global.user_name), ''T'', ''Y'', ''N''), ''Y'') modify_privilege
        FROM
            gl_coa_mappings map,
            gl_ledger_relationships glr,
            fnd_id_flex_structures_v from_coa,
            fnd_id_flex_structures_v to_coa
        WHERE
            map.from_coa_id = from_coa.id_flex_num
            AND map.coa_mapping_id = glr.sl_coa_mapping_id
            AND map.to_coa_id = to_coa.id_flex_num
            AND from_coa.application_id = 101
            AND from_coa.id_flex_code = ''GL#''
            AND to_coa.application_id = 101
            AND to_coa.id_flex_code = ''GL#''
            AND glr.primary_ledger_id = nvl(##$$LEDGID$$##, - 1)
    ) a',
      p_title                  => 'Chart of Accounts Mapping',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Chart of Accounts Mapping details for the selected Ledger ID/Name.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('SUCCESS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('COA_SEGMENT_RULES','COA_ACCOUNT_RULES'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: COA_MAPPING');



