debug('begin add_signature: DC_GL_SUBLEDGER_PERIOD_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6037',
      p_sig_id                 => 'DC_GL_SUBLEDGER_PERIOD_STATUS',
      p_sig_sql                => 'SELECT ps.application_id,
 ps.ledger_id,
ps.period_num,
 ps.period_name,
 ps.closing_status,
 ps.start_date,
 ps.end_date,
 ps.period_type,
 ps.period_year,
 ps.adjustment_period_flag,
 ps.creation_date, 
 ps.created_by, 
 ps.last_update_date,
 ps.last_updated_by
FROM gl_period_statuses ps, gl_ledgers led
WHERE ps.ledger_id = led.ledger_id+0
AND led.ledger_id = ##$$LEDGID$$##
AND led.period_set_name = ''##$$CALNAME$$##''
AND period_year >= (select distinct period_year-1 
                      from gl_periods 
                            where period_name = ''##$$PERNAME$$##''
                              and period_set_name = ''##$$CALNAME$$##'')
AND period_year <= (select distinct period_year+1 
                      from gl_periods 
                            where period_name = ''##$$PERNAME$$##''
                              and period_set_name = ''##$$CALNAME$$##'')
order by  ps.application_id, ps.period_year, ps.period_num',
      p_title                  => 'GL and Subledger Period Statuses',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This provides the period status in General Ledger as well as in subledger applications for the selected Ledger.',
      p_solution               => '',
      p_success_msg            => 'This provides the period status in General Ledger as well as in subledger applications for the selected Ledger.',
