debug('begin add_signature: DC_COUNT_OF_ACTUAL_BUDGET_ENCUMBRANCE_JOURNALS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6072',
      p_sig_id                 => 'DC_COUNT_OF_ACTUAL_BUDGET_ENCUMBRANCE_JOURNALS',
      p_sig_sql                => 'SELECT GJH.LEDGER_ID,
        GJH.ACTUAL_FLAG,
        GJH.PERIOD_NAME,
        STATUS,
        COUNT(*)
FROM GL_JE_HEADERS GJH,
      GL_LEDGERS LED,
      GL_PERIODS GP, 
      GL_PERIODS GP1
WHERE GJH.LEDGER_ID=LED.LEDGER_ID
AND LED.period_set_name = ''##$$CALNAME$$##''
AND GJH.period_name=GP.period_name
AND GP.period_set_name = ''##$$CALNAME$$##''
AND GP.period_year=GP1.period_year
AND GP1.period_set_name = ''##$$CALNAME$$##''
AND GP1.period_name = ''##$$PERNAME$$##'' 
GROUP BY GJH.LEDGER_ID,
        GJH.ACTUAL_FLAG,
        GJH.PERIOD_NAME,
        STATUS',
