debug('begin add_signature: DC_SUMMARY_TEMPLATES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6211',
      p_sig_id                 => 'DC_SUMMARY_TEMPLATES',
      p_sig_sql                => 'SELECT st.template_name "Template Name"
,      st.concatenated_description " Template"
,       FLVl.meaning|| ''(''  || account_category_code ||'')'' "Account Category Meaning/Code" 
,       FLV2.meaning|| ''(''  || st.status  ||'')'' "Template Status/Code" 
,  st.start_actuals_period_name "Earliest Period"
,  to_char(st.max_code_combination_id) "MAX Combination ID"
  ,        to_char(st.last_update_date, ''DD-Mon-YYYY'') "Last Updated on"
FROM GL_SUMMARY_TEMPLATES st,
FND_LOOKUP_VALUES FLVl,
FND_LOOKUP_VALUES FLV2
WHERE st.ledger_id =  ##$$LEDGID$$##
  and FLVl.LOOKUP_CODE(+)=st.account_category_code and FLVl.lookup_type(+)  =''ACCOUNT_CATEGORY_CODE''
  and FLV2.LOOKUP_CODE(+)=st.status and FLV2.lookup_type(+)  = ''SUMMARY_STATUS''
  and FLVl.language=''US'' and FLV2.language =''US''
ORDER BY 1,2',
      p_title                  => 'Summary Templates',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'GL_SUMMARY_TEMPLATES stores the summary account templates you define using the Summary Accounts form.
Each row includes the start period name, the description and the template contents.
STATUS is usually ''F'' for "Current".
When you first add a template, STATUS is ''A'' until the Add/Delete Summary Templates program completes and sets STATUS to ''F''.
When you delete a template, STATUS is ''D'' until the Add/Delete Summary Templates program completes and deletes the row.',
      p_solution               => 'No Summary Templates exists for the selected Ledger.',
      p_success_msg            => 'This provides the Summary Templates defined for the selected Ledger.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: DC_SUMMARY_TEMPLATES');



debug('begin add_signature: DC_ACCOUNT_ATTRIBUTES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6210',
      p_sig_id                 => 'DC_ACCOUNT_ATTRIBUTES',
      p_sig_sql                => 'SELECT  cc.concatenated_segments "Code Combination",
        cc.chart_of_accounts_id "COA ID",
        cc.enabled_flag "Enabled Flag",
        cc.summary_flag "Summary Falg", 
        (SELECT DISTINCT l.meaning  FROM fnd_lookup_values l  
                                    WHERE l.lookup_type = ''ACCOUNT_TYPE''
                                    AND l.language      = ''US''  
                                    AND l.lookup_code   = cc.gl_account_type) || ''(''|| cc.GL_account_type || '')'' as "Account Type",
