debug('begin add_signature: DC_FSG_REPORT_DEFINITION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6741',
      p_sig_id                 => 'DC_FSG_REPORT_DEFINITION',
      p_sig_sql                => 'Select ''----------------------'' "FSG Component", ''----------------------'' "FSG Component Value" from dual
UNION ALL
select ''FSG Report Name '', rr.name "Report Component Information" from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''FSG Report Title '', rr.report_title from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''FSG Report Description '', nvl(rr.description, ''No Description Available'') from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Row Set Name '', rras.name from rg_reports rr, rg_report_axis_sets rras where rr.row_set_id = rras.axis_set_id and rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Column Set Name '', rras1.name from rg_reports rr, rg_report_axis_sets rras1 where rr.column_set_id = rras1.axis_set_id and rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Content Set Name '', NVL(rrcs.name, ''No Content set associated for this FSG Report'') from rg_reports rr, rg_report_content_sets rrcs where rr.content_set_id = rrcs.content_set_id (+) and rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Row Order Name '', NVL(rro.name,''No Row Order associated for this FSG Report'') from rg_reports rr, rg_row_orders rro where rr.row_order_id = rro.row_order_id (+) and rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Display Set Name '', NVL(rrds.name,''No Display Set associated for this FSG Report'') from rg_reports rr, rg_report_display_sets rrds where rr.report_display_set_id = rrds.report_display_set_id (+) and rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Segment Override '', NVL(rr.segment_override, ''No Segment Override defined with this FSG Report'') from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Currency '', NVL(rr.unit_of_measure_id,''No Currency Code associated for this FSG Report'') from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Rounding Option '', decode(rr.rounding_option, ''C'', ''Calculate then Round'', ''R'', ''Round then Caluculate'', rr.rounding_option) from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Level of Detail '', NVL(decode(rr.minimum_display_level, ''1'', ''Financial Analyst'', ''2'', ''Supervisor'', ''3'', ''Controller'', rr.minimum_display_level), ''No Level of Detail associated for this FSG Report'') from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)
UNION ALL
select ''Output Option '', decode(rr.output_option, ''P'', ''Spreadsheet'',
''S'', ''Tab Delimited'',
''R'', ''Text'',
''Y'', ''XML'',
''B'', ''XBRL'', rr.output_option) from rg_reports rr where rr.report_id = NVL(##$$REPID$$##, -1)',
      p_title                  => 'FSG Report Definition',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No rows selected for FSG report '||mask_text(g_rep_id, nvl( upper(''), 'NO_MASK') )||'.
',
      p_solution               => 'Nothing to report.',
      p_success_msg            => 'This provides ALL the component information related to the selected FSG report '||mask_text(g_rep_name, nvl( upper(''), 'NO_MASK') )||'.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: DC_FSG_REPORT_DEFINITION');



debug('begin add_signature: DC_FSG_ROWSET_ACCOUNT_ASSIGNMENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6805',
      p_sig_id                 => 'DC_FSG_ROWSET_ACCOUNT_ASSIGNMENTS',
      p_sig_sql                => 'SELECT cont.axis_seq  "RowSet Seq"
,      cont.sign  "SIGN"
,      gll.name "Ledger Name"
,      gll.short_name||''-''||cont.segment1_low||''-''||cont.segment2_low||''-''||cont.segment3_low||''-''||cont.segment4_low||''-''||cont.segment5_low "Accounts LOW"
,      gll.short_name||''-''||cont.segment1_high||''-''||cont.segment2_high||''-''||cont.segment3_high||''-''||cont.segment4_high||''-''||cont.segment5_high "Accounts HIGH"
,      cont.ledger_segment_type||''-''||cont.segment1_type||''-''||cont.segment2_type||''-''||cont.segment3_type||''-''||cont.segment4_type||''-''||cont.segment5_type "Display"
,      decode(cont.range_mode, ''Y'', ''Enabled'', ''N'', ''Not Enabled'', cont.range_mode) "Summary Flag"
,      lookup.meaning "Activity Type"
FROM   rg_report_axis_contents cont 
,      gl_lookups lookup 
,      gl_ledgers gll 
WHERE  lookup.lookup_type = ''DR_CR_NET_CODE''
AND    lookup.lookup_code (+) = cont.dr_cr_net_code 
AND    cont.ledger_id = gll.ledger_id (+)
AND    cont.axis_set_id = NVL(##$$ROWSET$$##, -1) 
AND cont.axis_seq= ''##$$FK1$$##''
ORDER BY cont.axis_seq',
