debug('begin add_signature: DC_FSG_ROWSET');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6738',
      p_sig_id                 => 'DC_FSG_ROWSET',
      p_sig_sql                => 'SELECT            rras.name "Row Set Name", 
                  rxt.taxonomy_name "XBRL Taxonomy",
