                      rra.display_format "Format Mask", 
                        decode(rra.display_units, 9, ''Billions'', 6, ''Millions'', 3, ''Thousands'', 0, ''Units'', -2, ''Percentiles'', rra.display_units) "Factor",
                     decode(rra.display_level, ''1'', ''Financial Analyst'', ''2'', ''Supervisor'', ''3'', ''Controller'', rra.display_level) "Level of Detail",                        
                                          decode(rra.display_flag, ''Y'', ''Yes'', ''N'', ''No'', rra.display_flag) "Display Row",
                     decode(rra.display_zero_amount_flag, ''Y'', ''Yes'', ''N'', ''No'',rra.display_zero_amount_flag) "Display Zero",
                     decode(rra.change_sign_flag, ''Y'', ''Yes'', ''N'', ''No'',rra.change_sign_flag) "Change Sign",
                     decode(rra.change_variance_sign_flag, ''Y'', ''Yes'', ''N'', ''No'',rra.change_variance_sign_flag)"Change Sign on Variance",
                                          decode(rra.calculation_precedence_flag,''Y'', ''Yes'', ''N'', ''No'',rra.calculation_precedence_flag) "Override Row Calculations", 
                  rra.axis_name "Row Name",
                                                                   rra.percentage_divisor_seq "Percent of Row" ,
                                                                   rxmv.element_label "XBRL Element"                                    
                   FROM   rg_report_axes rra, rg_report_axis_sets rras , rg_report_standard_axes_vl rgsav, rg_xbrl_map_v rxmv, rg_xbrl_taxonomies rxt
                    WHERE  rras.axis_set_id = rra.axis_set_id
                    and rra.standard_axis_id = rgsav.standard_axis_id(+)
                    and rra.element_id = rxmv.element_id (+)
                    and rras.taxonomy_id = rxt.taxonomy_id (+)
                    and rras.axis_set_id = NVL(##$$ROWSET$$##, -1) 
                    ORDER BY axis_seq',
