      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('DC_FSG_ROWSET_ACCOUNT_ASSIGNMENTS','DC_FSG_ROWSET_CALCULATIONS'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
