      p_sig_sql                => 'select rrcs.name "Content Set",
          decode(rrcs.report_run_type, ''S'', ''Sequential'', ''P'', ''Parallel'', rrcs.report_run_type) "Type",
          decode(rrcs.security_flag, ''Y'', ''Enabled'', ''N'', ''Not Enabled'', rrcs.security_flag) "Enable Security",
          rgco.override_seq "Account Assignments Seq#",
      --   gll.name "Ledger Name",
gll.short_name||''-''||rgco.segment1_low||''-''||rgco.segment2_low||''-''||rgco.segment3_low||''-''||rgco.segment4_low||''-''||rgco.segment5_low||''-''||rgco.segment6_low "Account Ranges LOW"
, gll.short_name||''-''||rgco.segment1_high||''-''||rgco.segment2_high||''-''||rgco.segment3_high||''-''||rgco.segment4_high||''-''||rgco.segment5_high||''-''||rgco.segment6_high "Account Ranges HIGH"
, rgco.ledger_segment_type||''-''||rgco.segment1_type||''-''||rgco.segment2_type||''-''||rgco.segment3_type||''-''||rgco.segment4_type||''-''||rgco.segment5_type||''-''||rgco.segment6_type "Display" ,         
 decode(rgco.range_mode, ''Y'', ''Enabled'', ''N'', ''Not Enabled'', rgco.range_mode) "Summary"
from    RG_REPORT_CONTENT_SETS  rrcs, 
        rg_report_content_overrides rgco, 
        gl_ledgers gll
where     rrcs.content_set_id = rgco.content_set_id(+)
and       rgco.ledger_id = gll.ledger_id (+)
and       rrcs.content_set_id = NVL(##$$CONTENTSET$$##, -1) 
order by rgco.override_seq asc',
