debug('begin add_signature: DC_FSG_ROWORDER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '6935',
      p_sig_id                 => 'DC_FSG_ROWORDER',
      p_sig_sql                => 'SELECT rro.name "Row Order", 
 decode(rro.security_flag, ''Y'', ''Enabled'', ''N'', ''Not Enabled'', rro.security_flag) "Enable Security",
 seq.segment_sequence "Account Display Seq#",
 seq.seg_name "Segment",
lookup2.meaning  "Order By",
 lookup.meaning "Display", 
 seq.segment_width "Width"
FROM rg_row_segment_sequences_v seq ,
                      rg_lookups lookup ,
                      rg_lookups lookup2,
                      RG_ROW_ORDERS rro 
                 WHERE  lookup.lookup_type = ''SEG_DISPLAY_TYPE''
                 and    seq.row_order_id = rro.row_order_id
                 AND    lookup.lookup_code (+) = seq.seg_display_type
                 AND    lookup2.lookup_type = ''ORDERING_TYPE''
                 AND    lookup2.lookup_code (+) = seq.seg_order_type
                AND seq.application_column_name <> ''LEDGER_SEGMENT''
                 AND    rro.row_order_id = ##$$ROWORDER$$##
UNION
SELECT  rro.name "Row Order", 
 decode(rro.security_flag, ''Y'', ''Enabled'', ''N'', ''Not Enabled'', rro.security_flag) "Enable Security",
 seq.segment_sequence "Account Display Seq#",
 seq.seg_name "Segment",
lookup2.meaning  "Order By",
 decode(seq.seg_display_type, ''D'', ''Ledger Name'', ''V'', ''Ledger Short Name'', ''B'', ''Ledger Short Name and Ledger Name'', seq.seg_display_type) "Display", 
 seq.segment_width "Width"
FROM rg_row_segment_sequences_v seq ,
                      rg_lookups lookup ,
                      rg_lookups lookup2,
                      RG_ROW_ORDERS rro 
                 WHERE  lookup.lookup_type = ''SEG_DISPLAY_TYPE''
                 and    seq.row_order_id = rro.row_order_id
                 AND    lookup.lookup_code (+) = seq.seg_display_type
                 AND    lookup2.lookup_type = ''LEDGER_ORDERING_TYPE''
                 AND    lookup2.lookup_code (+) = seq.seg_order_type
                AND seq.application_column_name = ''LEDGER_SEGMENT''
                 AND    rro.row_order_id = NVL(##$$ROWORDER$$##, -1)',
