debug('begin add_signature: FSG_APOSTROPHE_IN_COLUMN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22445',
      p_sig_id                 => 'FSG_APOSTROPHE_IN_COLUMN',
      p_sig_sql                => 'SELECT
    rr.name         "Report Name",
    '' Row Set'' "Type",
    rras.name       "Row Set or Column Set Name",
    rra.axis_name   "Row or Column  Name",
    rra.axis_seq    "Sequence Number"
FROM
    rg_report_axes        rra,
    rg_report_axis_sets   rras,
    rg_reports            rr
WHERE
    rr.row_set_id = rras.axis_set_id
    AND rras.axis_set_id = rra.axis_set_id
    AND rra.axis_set_id =   NVL(##$$ROWSET$$##, -1) 
    AND ( rra.axis_name LIKE '' %chr(39)%''
          OR rra.axis_name LIKE ''%''''%'' )
UNION
SELECT
    rr.name         "Report Name",
    '' Column Set'' "Type",
    rras.name       "Row Set or Column Set Name",
    rra.axis_name   "Row or Column  Name",
    rra.axis_seq    "Sequence Number"
FROM
    rg_reports            rr,
    rg_report_axes        rra,
    rg_report_axis_sets   rras
WHERE
    rr.column_set_id = rras.axis_set_id
    AND rras.axis_set_id = rra.axis_set_id
    AND rra.axis_set_id =  NVL(##$$COLUMNSET$$##, -1) 
    AND ( rra.axis_name LIKE '' %chr(39)%''
          OR rra.axis_name LIKE ''%''''%'' )',
