debug('begin add_signature: EBS_FIN_JE_LINE_BUD_ORG_ACCOUNT_RANGE_ASSIGNMENT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30939',
      p_sig_id                 => 'EBS_FIN_JE_LINE_BUD_ORG_ACCOUNT_RANGE_ASSIGNMENT',
      p_sig_sql                => 'SELECT
    glc.code_combination_id,
    glc.concatenated_segments,
    sub.funding_budget_name,
    sub.budget_status,
    sub.require_budget_journals_flag,
    sub.latest_opened_year,
    sub.budget_organization_id,
    sub.budget_organization_name,
    sub.organization_start_date,
    sub.organization_end_date,
    sub.funds_check_level_code,
    sub.check_level_meaning,
    sub.amount_type,
    sub.boundary_code,
    sub."from" AS "FROM",
    sub."to" AS "TO"
FROM
    gl_je_headers gjh
INNER JOIN
    gl_je_lines gjl
    ON gjh.je_header_id = gjl.je_header_id
INNER JOIN
    gl_code_combinations_kfv glc
    ON glc.code_combination_id = gjl.code_combination_id
INNER JOIN
    (
        SELECT
            bop.funding_budget_name,
            bud.status AS budget_status,
            bud.ledger_id,
            bud.require_budget_journals_flag,
            bud.latest_opened_year,
            bud.date_closed,
            bor.budget_entity_id AS budget_organization_id,
            bor.name AS budget_organization_name,
            bor.start_date AS organization_start_date,
            bor.end_date AS organization_end_date,    
            bop.funds_check_level_code,
            glm.meaning AS check_level_meaning,
            bop.amount_type,
            bop.boundary_code,
            rtrim(ltrim(bas.segment1_low)) AS segment1_low,
            rtrim(ltrim(bas.segment2_low)) AS segment2_low,
            rtrim(ltrim(bas.segment3_low)) AS segment3_low,
            rtrim(ltrim(bas.segment4_low)) AS segment4_low,
            rtrim(ltrim(bas.segment5_low)) AS segment5_low,
            rtrim(ltrim(bas.segment6_low)) AS segment6_low,
            rtrim(ltrim(bas.segment7_low)) AS segment7_low,
            rtrim(ltrim(bas.segment8_low)) AS segment8_low,
            rtrim(ltrim(bas.segment9_low)) AS segment9_low,
            rtrim(ltrim(bas.segment10_low)) AS segment10_low,
            rtrim(ltrim(bas.segment1_high)) AS segment1_high,
            rtrim(ltrim(bas.segment2_high)) AS segment2_high,
            rtrim(ltrim(bas.segment3_high)) AS segment3_high,
            rtrim(ltrim(bas.segment4_high)) AS segment4_high,
            rtrim(ltrim(bas.segment5_high)) AS segment5_high,
            rtrim(ltrim(bas.segment6_high)) AS segment6_high,
            rtrim(ltrim(bas.segment7_high)) AS segment7_high,
            rtrim(ltrim(bas.segment8_high)) AS segment8_high,
            rtrim(ltrim(bas.segment9_high)) AS segment9_high,
            rtrim(ltrim(bas.segment10_high)) AS segment10_high,
            rtrim(ltrim(bas.segment1_low
                || ''-''
                || bas.segment2_low
                || ''-''
                || bas.segment3_low
                || ''-''
                || bas.segment4_low
                || ''-''
                || bas.segment5_low
                || ''-''
                || bas.segment6_low
                || ''-''
                || bas.segment7_low
                || ''-''
                || bas.segment8_low
                || ''-''
                || bas.segment9_low
                || ''-''
                || bas.segment10_low, ''-''), ''-'') AS "from",
            rtrim(ltrim(bas.segment1_high
                || ''-''
                || bas.segment2_high
                || ''-''
                || bas.segment3_high
                || ''-''
                || bas.segment4_high
                || ''-''
                || bas.segment5_high
                || ''-''
                || bas.segment6_high
                || ''-''
                || bas.segment7_high
                || ''-''
                || bas.segment8_high
                || ''-''
                || bas.segment9_high
                || ''-''
                || bas.segment10_high, ''-''), ''-'') AS "to"              
        FROM
            apps.gl_budget_entities bor
        INNER JOIN
            apps.gl_budget_assignment_ranges_v bas
            ON bor.ledger_id = bas.ledger_id
            AND bor.budget_entity_id = bas.budget_entity_id
        INNER JOIN
            apps.gl_budorg_bc_options_v bop
            ON bas.range_id = bop.range_id
        INNER JOIN
            apps.gl_budget_versions bve
            ON bop.funding_budget_version_id = bve.budget_version_id
            AND bop.funding_budget_name = bve.budget_name
        INNER JOIN
            apps.gl_budgets bud
            ON bve.budget_name = bud.budget_name
        INNER JOIN
            apps.gl_lookups glm
            ON bop.funds_check_level_code = glm.lookup_code 
            AND glm.lookup_type = ''FUNDS_CHECK_LEVEL''
        WHERE
            bas.ledger_id = ##$$LEDGID$$##
            AND nvl(bor.start_date, SYSDATE) <= SYSDATE
            AND nvl(bor.end_date, SYSDATE) >= SYSDATE
            AND bor.status_code = ''C''
    ) sub
    ON NVL(glc.segment1, ''0'') BETWEEN NVL(sub.segment1_low, ''0'') AND NVL(sub.segment1_high, ''0'')
    AND NVL(glc.segment2, ''0'') BETWEEN NVL(sub.segment2_low, ''0'') AND NVL(sub.segment2_high, ''0'')
    AND NVL(glc.segment3, ''0'') BETWEEN NVL(sub.segment3_low, ''0'') AND NVL(sub.segment3_high, ''0'')
    AND NVL(glc.segment4, ''0'') BETWEEN NVL(sub.segment4_low, ''0'') AND NVL(sub.segment4_high, ''0'')
    AND NVL(glc.segment5, ''0'') BETWEEN NVL(sub.segment5_low, ''0'') AND NVL(sub.segment5_high, ''0'')  
    AND NVL(glc.segment6, ''0'') BETWEEN NVL(sub.segment6_low, ''0'') AND NVL(sub.segment6_high, ''0'')
    AND NVL(glc.segment7, ''0'') BETWEEN NVL(sub.segment7_low, ''0'') AND NVL(sub.segment7_high, ''0'')
    AND NVL(glc.segment8, ''0'') BETWEEN NVL(sub.segment8_low, ''0'') AND NVL(sub.segment8_high, ''0'')  
    AND NVL(glc.segment9, ''0'') BETWEEN NVL(sub.segment9_low, ''0'') AND NVL(sub.segment9_high, ''0'')
    AND NVL(glc.segment10, ''0'') BETWEEN NVL(sub.segment10_low, ''0'') AND NVL(sub.segment10_high, ''0'')
WHERE
    gjh.je_batch_id = ##$$JE_BATCH_ID$$##    
GROUP BY
    glc.code_combination_id,
    glc.concatenated_segments,
    sub.funding_budget_name,
    sub.budget_status,
    sub.require_budget_journals_flag,
    sub.latest_opened_year,
    sub.budget_organization_id,
    sub.budget_organization_name,
    sub.organization_start_date,
    sub.organization_end_date,
    sub.funds_check_level_code,
    sub.check_level_meaning,    
    sub.amount_type,
    sub.boundary_code,
    sub."from",
    sub."to"',
      p_title                  => 'CCIDs in Batch Within Budget Organization Account Range',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Journal Code Combinations Falling Within an Organization''s Account Range Assignment. <br> 

When processing journal entries, certain Journal Line CCIDs fall within the Account Range Assignment of a Budget Organization. This may cause Funds Checking validation errors etc., The output is to identify relevant information regarding the Budget Organization Assignments for all the Accounts Code Combinations (Detailed Accounts) used in the Journal batch having the issue and can correct them easily in EBS Application. <br> 

Refer to, [2960957.1] R12 Scripts to Check Budgetary Control Settings for Detailed Accounts in a Batch.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_JE_LINE_BUD_ORG_ACCOUNT_RANGE_ASSIGNMENT');



debug('begin add_signature: EBS_FIN_CCID_IN_BATCH_FOR_SUMMARY_TEMPLATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30940',
      p_sig_id                 => 'EBS_FIN_CCID_IN_BATCH_FOR_SUMMARY_TEMPLATE',
      p_sig_sql                => 'SELECT
    gld.code_combination_id AS detailed_acc_ccid,
    gld.concatenated_segments AS detailed_acc_conc_seg,
    gld.summary_flag AS detailed_acc_summary_flag,
    glc.code_combination_id AS template_ccid,
    glc.concatenated_segments AS template_conc_seg,
    glc.summary_flag AS template_summary_flag,
    bud.budget_name,
    bud.status AS budget_status,
    bud.ledger_id,
    bud.require_budget_journals_flag,
    bud.latest_opened_year,
    bud.date_closed,
    glc.template_id,
    gst.template_name,
    gst.status AS template_status,
    gst.concatenated_description,
    gsm.funds_check_level_code,
    glm.meaning AS check_level_meaning,    
    gsm.dr_cr_code,
    gsm.amount_type,
    gsm.boundary_code
FROM
    gl_je_headers gjh
INNER JOIN
    gl_je_lines gjl
    ON gjh.je_header_id = gjl.je_header_id
INNER JOIN
    gl_code_combinations_kfv gld
    ON gjl.code_combination_id = gld.code_combination_id
INNER JOIN
    gl_account_hierarchies gah
    ON gld.code_combination_id = gah.detail_code_combination_id
INNER JOIN
    gl_code_combinations_kfv glc
    ON gah.template_id = glc.template_id
INNER JOIN
    gl_summary_bc_options gsm
    ON gah.template_id = gsm.template_id
INNER JOIN
    gl_summary_templates gst
    ON gah.template_id = gst.template_id
INNER JOIN
    gl_budget_versions bve
    ON gsm.funding_budget_version_id = bve.budget_version_id
INNER JOIN
    gl_budgets bud
    ON bve.budget_name = bud.budget_name  
INNER JOIN
    apps.gl_lookups glm
    ON gsm.funds_check_level_code = glm.lookup_code 
    AND glm.lookup_type = ''FUNDS_CHECK_LEVEL''    
WHERE
    bud.ledger_id = ##$$LEDGID$$##
    AND gjh.je_batch_id = ##$$JE_BATCH_ID$$##
GROUP BY
    gld.code_combination_id,
    gld.concatenated_segments,
    gld.summary_flag,
    glc.code_combination_id,
    glc.concatenated_segments,
    glc.summary_flag,
    bud.budget_name,
    bud.status,
    bud.ledger_id,
    bud.require_budget_journals_flag,
    bud.latest_opened_year,
    bud.date_closed,
    glc.template_id,
    gst.template_name,
    gst.status,
    gst.concatenated_description,
    gsm.funds_check_level_code,
    glm.meaning,    
    gsm.dr_cr_code,
    gsm.amount_type,
    gsm.boundary_code',
      p_title                  => 'CCIDs in Batch Linked to a Summary Template',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Journal Code Combinations used in the journal batch were attached to a Summary Template. <br>

This output will provide relevant information regarding Budgetary Control configuration for the Summary Templates that includes all the Account Code Combinations (Detailed Accounts) in a batch.

<br> Refer to, [2960957.1] R12 Scripts to Check Budgetary Control Settings for Detailed Accounts in a Batch.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
