debug('begin add_signature: RECURRING_JE_FORMULA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22311',
      p_sig_id                 => 'RECURRING_JE_FORMULA',
      p_sig_sql                => 'SELECT 
 grlcr.rule_num step,
 grlcr.operator,
 grlcr.amount,
 gll.ledger_id,
 gll.name ledger_name,
 gcc.concatenated_segments account,
 decode(grlcr.actual_flag, ''A'', ''Actual'', ''B'', ''Budget'', ''E'', ''Encumbrance'', grlcr.actual_flag) balance_type,
 grlcr.amount_type,
 grlcr.ledger_currency,
 decode(grlcr.currency_type,''T'', ''Total'', ''S'', ''Statistical'',''E'', ''Entered'',grlcr.currency_type) currency_type,
 grlcr.entered_currency,
 decode(grlcr.relative_period_code, ''C'', ''Current Period'',''S'', ''Same period a Year Ago'', ''P'', ''Previous Period'', grlcr.relative_period_code) period
FROM
    gl_recurring_line_calc_rules grlcr, gl_recurring_lines grl, gl_code_combinations_kfv gcc, gl_ledgers gll
WHERE grl.recurring_header_id = grlcr.recurring_header_id
AND grl.recurring_line_num = grlcr.recurring_line_num
AND grlcr.assigned_code_combination = gcc.code_combination_id(+)
AND grlcr.ledger_id = gll.ledger_id(+)
AND    grl.recurring_header_id = ##$$FK3$$##
    AND grl.recurring_line_num = ##$$FK4$$##
ORDER BY
    grlcr.rule_num',
