debug('begin add_signature: UNBALANCED_RECONCILIATION_ACCOUNTED_AMOUNT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12323',
      p_sig_id                 => 'UNBALANCED_RECONCILIATION_ACCOUNTED_AMOUNT',
      p_sig_sql                => 'SELECT l.ledger_id "Ledger ID", 
le.Name "Ledger Name", 
jgzz_recon_id "Reconcilation Identifier",
SUM(nvl(accounted_cr, 0)) "Sum of Accounted CR",
SUM(nvl(accounted_dr, 0)) "Sum of Accounted DR"
FROM gl_je_lines l,
gl_je_lines_recon r,
gl_ledgers le
WHERE l.je_header_id = r.je_header_id
AND l.je_line_num = r.je_line_num
AND le.ledger_id = l.Ledger_id
-- AND r.jgzz_recon_id = &rec_id
AND jgzz_recon_status = ''R''
AND l.ledger_id = ##$$LEDGID$$## 
GROUP BY r.jgzz_recon_id,l.ledger_id, le.Name
HAVING SUM(nvl(accounted_cr, 0))<> SUM(nvl(accounted_dr, 0))',
      p_title                  => 'Unbalanced Reconciliation Accounted Amount',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The reconciliation seems to be unbalanced or missing journal lines were spotted in the problematic reconciliation.',
      p_solution               => '<ul><li> [1516180.1] R12: GL Reconciliation - Unbalanced (Datafix). </li></ul>',
