AND le.ledger_id = l.Ledger_id
-- AND r.jgzz_recon_id = &rec_id
AND jgzz_recon_status = ''R''
AND l.ledger_id = ##$$LEDGID$$## 
GROUP BY r.jgzz_recon_id,l.ledger_id, le.Name
HAVING SUM(nvl(entered_cr,   0))<> SUM(nvl(entered_dr,   0))',
      p_title                  => 'Unbalanced Reconciliation Entered Amount',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The reconciliation seems to be unbalanced or missing journal lines were spotted in the problematic reconciliation.',
