debug('begin add_signature: GL_JOURNAL_LEAD_TRAIL_SPACES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12319',
      p_sig_id                 => 'GL_JOURNAL_LEAD_TRAIL_SPACES',
      p_sig_sql                => 'select distinct gb.je_batch_id
, REGEXP_REPLACE(REGEXP_REPLACE(gb.name, ''\s+$'', ''~''), ''^[ \t]+'', ''~'') "Batch Name"
, REGEXP_REPLACE(REGEXP_REPLACE(gb.description, ''\s+$'', ''~''), ''^[ \t]+'', ''~'') "Batch Description"
/* , gb.name "Batch Name"
, gb.description
, (length(gb.name)- length(ltrim(gb.name))) "No. of Leading Spaces"
, (length(gb.name)- length(rtrim(gb.name))) "No. of Trailing Spaces" */
, gh.ledger_id "Ledger ID"
from gl_je_batches gb,
gl_je_headers gh,
gl_period_statuses gps
where gb.je_batch_id = gh.je_batch_id
and gps.ledger_id = gh.ledger_id
and gps.closing_status in (''O'', ''F'')
and (gb.description <> trim(gb.description) OR gb.name <> trim(gb.name))
and gh.ledger_id =  ##$$LEDGID$$##',
      p_title                  => 'Journal Name With Lead Trail Spaces',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The above data contains leading or trailing spaces in the Journal Batch Name and/or Description. Values with spaces are shown between tilde (~).',
      p_solution               => '<ul><li>You can fix the problem identified in this section using this note.</li>
<li> [1135903.1] GLXJEENT: Journal Reversal gives Error FRM-40654: Record has been updated. Requery block to see change. </li></ul>',
      p_success_msg            => 'There are no leading or trailing spaces in the Journal Batch Name.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: GL_JOURNAL_LEAD_TRAIL_SPACES');



