debug('begin add_signature: GL_BATCH_STATUS_ERROR28');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12306',
      p_sig_id                 => 'GL_BATCH_STATUS_ERROR28',
      p_sig_sql                => 'SELECT
    ledger_name ledger_name,
    segment_type_code segment_type_code,
    segment_value segment_value,
    error_message error_message,
    record_id record_id
FROM
    (
        ( SELECT
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_norm_seg_vals'' error_message,
            parent_record_id record_id
        FROM
            gl_ledger_segment_values glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
            and gl.ledger_id=##$$LEDGID$$## 
        MINUS SELECT
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_norm_seg_vals'' error_message,
            record_id record_id
        FROM
            gl_ledger_norm_seg_vals glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
            and gl.ledger_id=##$$LEDGID$$## 
        ) UNION ( SELECT
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_segment_values'' error_message,
            record_id record_id
        FROM
            gl_ledger_norm_seg_vals glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
            and gl.ledger_id=##$$LEDGID$$## 
        MINUS SELECT
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_segment_values'' error_message,
            parent_record_id record_id
        FROM
            gl_ledger_segment_values glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
            and gl.ledger_id=##$$LEDGID$$## 
        )
    )
ORDER BY
    1,
    3,
    5 ASC',
      p_title                  => 'Error28 Showing Invalid Balancing Or Management Segment Value',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Error28 Showing invalid balancing or management segment Value',
      p_solution               => '[1390899.1] Troubleshooting Journal Batch Posting Status with Error%',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
