debug('begin add_signature: GL_BATCH_STATUS_ERROR3');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12305',
      p_sig_id                 => 'GL_BATCH_STATUS_ERROR3',
      p_sig_sql                => 'SELECT
    ledger_id ledger_id,
    batch_name batch_name,
    header_name header_name,
    batch_status batch_status,
    header_status header_status,
    line_status line_status
FROM
    (
        SELECT DISTINCT
            ledger_id ledger_id,
            b_name batch_name,
            h_name header_name,
            b_status batch_status,
            h_status header_status,
            l_status line_status
        FROM
            (
                WITH ledger AS (
                    SELECT UNIQUE
                        gpm.period_name,
                        gps.closing_status,
                        led.ledger_id
                    FROM
                        gl_ledgers led,
                        gl.gl_date_period_map gpm,
                        gl_period_statuses gps
                    WHERE
                    led.ledger_id=##$$LEDGID$$## 
                    AND
                        EXTRACT(YEAR FROM gpm.accounting_date) = EXTRACT(YEAR FROM SYSDATE)
                    AND
                        gpm.period_set_name = led.period_set_name
                    AND
                        gpm.period_type = led.accounted_period_type
                    AND
                        led.complete_flag = ''Y''
                    AND
                        led.first_ledger_period_name IS NOT NULL
                    AND
                        gps.ledger_id = led.ledger_id
                    AND
                        gpm.period_name = gps.period_name
                    AND
                        gps.application_id = 101
                    AND
                        gps.closing_status IN (
                            ''C'',''O'',''P'',''F''
                        )
                ) SELECT
                    jel.ledger_id ledger_id,
                    jeb.name b_name,
                    jeh.name h_name,
                    jeb.status b_status,
                    jeh.status h_status,
                    jel.status l_status
                FROM
                    gl_je_lines jel,
                    gl_je_headers jeh,
                    gl_je_batches jeb,
                    ledger led
                WHERE
                led.ledger_id=##$$LEDGID$$## 
                    and jeh.ledger_id = led.ledger_id
                AND
                    jeh.je_header_id = jel.je_header_id
                AND
                    jeb.je_batch_id = jeh.je_batch_id
                AND
                    jel.period_name = led.period_name
                AND
                    jeh.status = ''P''
                AND
                    jel.status = ''P''
                AND
                    jeb.status = ''E''
            )
    )',
      p_title                  => 'Error3 - Showing No Journal Entries For This Batch',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Error3 - Showing no journal entries for this batch',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: GL_BATCH_STATUS_ERROR3');



debug('begin add_signature: GL_POSTING_STATUS_ERROR7');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12307',
      p_sig_id                 => 'GL_POSTING_STATUS_ERROR7',
      p_sig_sql                => 'SELECT
ledger_id ledger_id,
name journal_name,
enabled_flag enabled_flag,
code_combination_range code_combination_range,
concatenated_segments concatenated_segments,
line_no line_no
FROM
(
SELECT
gl.ledger_id,
gh.name,
c.enabled_flag,
( ''Start Date:''
|| c.start_date_active
|| '' / End Date:''
|| c.end_date_active ) code_combination_range,
gcc.concatenated_segments,
l.je_line_num line_no
FROM
gl_je_lines l,
gl_code_combinations c,
gl_ledgers gl,
gl_je_headers gh,
gl_je_batches gb,
gl_code_combinations_kfv gcc
WHERE
gl.ledger_id = ##$$LEDGID$$## 
AND gh.status NOT IN (''P'',''U'')
AND l.status = ''U''
AND c.code_combination_id = gcc.code_combination_id
AND gh.je_header_id = l.je_header_id
AND gh.je_batch_id = gb.je_batch_id
AND gl.ledger_id = l.ledger_id
AND l.creation_date >= SYSDATE - 30
AND l.code_combination_id = c.code_combination_id
AND (c.enabled_flag = ''N''OR l.effective_date NOT BETWEEN nvl(c.start_date_active,l.effective_date) AND nvl(c.end_date_active,''31-DEC-4712''))
)',
      p_title                  => 'Error7 - Invalid Journal Lines',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When posting, the following error occurs: "Error7 - Showing invalid journal entry lines or no journal entry lines".',
      p_solution               => '[2105859.1] GLPPOS: Error7 - Showing Invalid Journal Entry Lines Or No Journal Entry Lines ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
