debug('begin add_signature: DOC_NUMBER_NOT_GENERATED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13121',
      p_sig_id                 => 'DOC_NUMBER_NOT_GENERATED',
      p_sig_sql                => 'SELECT
    head.name "Header Name",
    head.default_effective_date "Effective Date",
    head.je_category "Category",
    head.je_source "Source",
    ass.doc_sequence_assignment_id   "Doc Sequence Assignment Id",
    ass.method_code                  "Method",
    ass.start_date                   "Start Date",
    ass.end_date                     "End Date",
    COUNT(*)
FROM
    gl_je_headers                  head,
    fnd_doc_sequence_assignments   ass
WHERE
    head.doc_sequence_id = ass.doc_sequence_id
    AND head.je_category = ass.category_code
    AND trunc(default_effective_date) BETWEEN trunc(ass.start_date) AND trunc(ass.end_date)
    AND head.doc_sequence_value IS NULL
    AND head.ledger_id = ##$$LEDGID$$##
GROUP BY
    head.name,
    head.default_effective_date,
    head.je_category, 
    head.je_source, 
    ass.doc_sequence_assignment_id,
    ass.method_code,
    ass.start_date,                                                                                                                                
    ass.end_date
ORDER BY 1',
