debug('begin add_signature: REVERSAL_PERIOD_NOT_SET_ON_REPLICATED_SECONDARY_LEDGER_JOURNAL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13125',
      p_sig_id                 => 'REVERSAL_PERIOD_NOT_SET_ON_REPLICATED_SECONDARY_LEDGER_JOURNAL',
      p_sig_sql                => 'SELECT hs.name "Secondary journal name" , hs.je_category, 
  hp.accrual_rev_period_name "Primary  Rev Period Name", hs.ledger_id
FROM apps.gl_je_headers hp,
  apps.gl_je_headers hs
WHERE hs.parent_je_header_id IS NOT NULL
AND hs.parent_je_header_id    = hp.je_header_id
AND UPPER(hp.PERIOD_NAME)     = UPPER(''##$$PERNAME$$##'')
AND hs.je_category           IN
  (SELECT o.je_category_name
  FROM apps.gl_autoreverse_options o,
    apps.gl_autorev_criteria_sets s,
    gl_ledgers l
  WHERE l.criteria_set_id=  s.criteria_set_id
  AND o.criteria_set_id  = s.criteria_set_id
  AND o.autoreverse_flag = ''Y''
   and l.ledger_id             = hs.ledger_id
  )
AND hs.accrual_rev_period_name     IS NULL
AND NVL(hs.accrual_rev_status, ''X'') = ''X''
AND (SELECT status
  FROM apps.gl_je_headers hp
  WHERE hp.je_header_id = hs.parent_je_header_id ) = ''P''
AND (SELECT gll.ledger_category_code
  FROM apps.gl_ledgers gll
  WHERE gll.ledger_id = hs.ledger_id ) = ''SECONDARY''
AND hp.ledger_id      =  ##$$LEDGID$$##',
