debug('begin add_signature: AME_GL_ATT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8683',
      p_sig_id                 => 'AME_GL_ATT',
      p_sig_sql                => 'SELECT *
FROM
  (SELECT DISTINCT AttributesEO.ATTRIBUTE_ID AS ATTRIBUTE_ID ,
    AttributeUsagesEO.APPLICATION_ID         AS APPLICATION_ID ,
    AttributesEO.NAME                        AS ATTRIBUTE_NAME ,
    AttributesEO.DESCRIPTION                 AS DESCRIPTION ,
    AttributeUsagesEO.QUERY_STRING           AS QUERY_STRING ,
    Usd.Meaning                              AS DATA_TYPE ,
    Usl.Meaning                              AS USAGE_TYPE ,
    Usc.Meaning                              AS CATEGORY ,
    AttributesEO.START_DATE                  AS START_DATE ,
    AttributesEO.END_DATE                    AS END_DATE ,
    AttributeUsagesEO.START_DATE             AS START_DATE1 ,
    AttributeUsagesEO.END_DATE               AS END_DATE1 ,
    AttributesEO.ATTRIBUTE_TYPE              AS ATTRIBUTE_TYPE ,
    --Itc.USER_ITEM_CLASS_NAME                                                                                                                                                                              AS ITEM_CLASS ,
    ITC.NAME                                                                                                                                                                                                AS ITEM_CLASS ,
    DECODE(ame_utility_pkg.check_seeddb ,''N'',DECODE(Usc.Meaning ,''Mandatory'',''SeededDel'' ,DECODE(ame_utility_pkg.is_seed_user(AttributeUsagesEO.CREATED_BY) ,1,''SeededDel'' ,''UnseededDel'')) ,''UnseededDel'') AS SEEDED_DELETE ,
    DECODE(ame_utility_pkg.is_seed_user(AttributeUsagesEO.CREATED_BY) ,1,''SeededUpd'' ,''UnseededUpd'')                                                                                                        AS SEEDED_UPDATE
  FROM --AME_ATTRIBUTES_VL AttributesEO ,
    AME_ATTRIBUTES AttributesEO,
    AME_ATTRIBUTE_USAGES AttributeUsagesEO ,
    -- AME_ITEM_CLASSES_VL Itc ,
    AME_ITEM_CLASSES Itc ,
    FND_LOOKUP_VALUES Usl ,
    FND_LOOKUP_VALUES Usd ,
    FND_LOOKUP_VALUES Usc
  WHERE AttributesEO.ATTRIBUTE_ID = AttributeUsagesEO.ATTRIBUTE_ID
  AND AttributesEO.ITEM_CLASS_ID  = Itc.ITEM_CLASS_ID
  AND Usl.LOOKUP_TYPE             = ''AME_QUERY_USAGE_TYPE''
  AND Usl.LOOKUP_CODE             = AttributeUsagesEO.IS_STATIC
  AND Usl.ENABLED_FLAG            = ''Y''
  AND USL.LANGUAGE                =''US''
  AND Usd.LOOKUP_TYPE             = ''AME_ATTRIBUTE_DATA_TYPE''
  AND Usd.LOOKUP_CODE             = UPPER(AttributesEO.ATTRIBUTE_TYPE)
  AND Usd.ENABLED_FLAG            = ''Y''
  AND USD.LANGUAGE                =''US''
  AND Usc.LOOKUP_TYPE             = ''AME_ATTRIBUTE_CATEGORY''
  AND Usc.LOOKUP_CODE             = ame_utility_pkg.get_attribute_category(AttributesEO.ATTRIBUTE_ID)
  AND Usc.ENABLED_FLAG            = ''Y''
  AND USC.LANGUAGE                =''US''
  AND sysdate BETWEEN AttributesEO.start_date AND NVL(AttributesEO.end_date          -(1/84600),sysdate)
  AND sysdate BETWEEN AttributeUsagesEO.start_date AND NVL(AttributeUsagesEO.end_date-(1/84600),sysdate)
  AND sysdate BETWEEN Itc.start_date AND NVL(Itc.end_date                            -(1/84600),sysdate)
  AND Usc.Meaning                       = ''Others''
  AND AttributeUsagesEO.APPLICATION_ID IN
    (SELECT Application_Id FROM ame_Calling_Apps WHERE fnd_Application_Id = 101
    )
  ) QRSLT
ORDER BY application_Id DESC,
  ATTRIBUTE_Name DESC',
      p_title                  => 'AME GL Attributes',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There are no Required Attributes defined for AME.',
      p_solution               => 'Please refer the technical brief from the following note for the explanation of all GL related Attributes.<br>
[2038960.1] Oracle General Ledger Journal Approvals Integration with Oracle Approvals Management (AME) and Oracle Workflow.',
      p_success_msg            => 'This section displays all the Required Attributes for AME.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: AME_GL_ATT');



debug('begin add_signature: AME_GL_CONDITIONS');
