debug('begin add_signature: GL_AME_AG');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8691',
      p_sig_id                 => 'GL_AME_AG',
      p_sig_sql                => 'SELECT ApproverGroupEO.APPROVAL_GROUP_ID "##$$FK5$$##",
    ApproverGroupEO.APPROVAL_GROUP_ID,
    --ApproverGroupEO.START_DATE,
    --ApproverGroupEO.END_DATE,
    ApproverGroupConfigEO.APPROVAL_GROUP_ID AS APPROVAL_GROUP_ID1,
    ApproverGroupConfigEO.APPLICATION_ID,
    --ApproverGroupConfigEO.START_DATE AS START_DATE1,
    --ApproverGroupConfigEO.END_DATE   AS END_DATE1,
    ApproverGroupEO.NAME,
   -- ApproverGroupEO.USER_APPROVAL_GROUP_NAME,
    ApproverGroupEO.CREATED_BY,
    ApproverGroupEO.DESCRIPTION,
    ApproverGroupEO.QUERY_STRING,
    ApproverGroupEO.IS_STATIC,
    ApproverGroupEO.OBJECT_VERSION_NUMBER,
    ApproverGroupConfigEO.VOTING_REGIME,
    ApproverGroupConfigEO.ORDER_NUMBER,
    ApproverGroupConfigEO.CREATED_BY            AS CREATED_BY1,
    ApproverGroupConfigEO.OBJECT_VERSION_NUMBER AS OBJECT_VERSION_NUMBER1,
    QryLookup.Meaning                           AS USAGE_TYPE,
    VotingLookup.Meaning                        AS VOTING_REGIME_TL
  FROM --AME_APPROVAL_GROUPS_VL ApproverGroupEO,
    AME_APPROVAL_GROUPS ApproverGroupEO,
    AME_APPROVAL_GROUP_CONFIG ApproverGroupConfigEO,
    --FND_LOOKUPS QryLookup,
    FND_LOOKUP_VALUES QryLookup,
    --FND_LOOKUPS VotingLookup
    FND_LOOKUP_VALUES VotingLookup
  WHERE ApproverGroupEO.APPROVAL_GROUP_ID = ApproverGroupConfigEO.APPROVAL_GROUP_ID
  AND QryLookup.lookup_type               = ''AME_QUERY_USAGE_TYPE''
  AND QryLookup.LANGUAGE                  =''US''
  AND QryLookup.lookup_code               = ApproverGroupEO.is_static
  AND VotingLookup.lookup_type            = ''AME_APG_VOTING_REGIME''
  AND VotingLookup.LANGUAGE               = ''US''
  AND VotingLookup.lookup_code            = ApproverGroupConfigEO.VOTING_REGIME
  AND sysdate BETWEEN ApproverGroupEO.start_date AND NVL(ApproverGroupEO.end_date            -(1/84600),sysdate)
  AND sysdate BETWEEN ApproverGroupConfigEO.start_date AND NVL(ApproverGroupConfigEO.end_date-(1/84600),sysdate)
  AND ApproverGroupConfigEO.APPLICATION_ID =
    ( SELECT application_Id FROM ame_Calling_Apps WHERE fnd_Application_Id = 101
    )
    
  AND ApproverGroupEO.Name               IN
    (SELECT SUBSTR(aa.description, 23)
    FROM ame_Actions aa,
      AME_ACTION_USAGES AAU
    WHERE aa.action_id     = aau.action_Id
    AND aau.rule_id        = ##$$FK3$$##
    --AND aa.action_type_id IN (10020, 10006, 10007)  
    )
AND exists (select m.APPROVAL_GROUP_ID FROM AME_APPROVAL_GROUP_MEMBERS m WHERE approval_group_Id =ApproverGroupEO.APPROVAL_GROUP_ID)
  
ORDER BY ORDER_NUMBER',
      p_title                  => 'AME Approval Groups',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There are no Approval groups defined for GL Journals.',
      p_solution               => 'Refer following note on how to define Approval Groups:<br>
[2038960.1] Oracle General Ledger Journal Approvals Integration with Oracle Approvals Management (AME) and Oracle Workflow.
',
      p_success_msg            => 'This section displays all the Approval groups defined in the system for GL Journals.<br>
Refer following note on how to define Approval Groups:<br>
[2038960.1] Oracle General Ledger Journal Approvals Integration with Oracle Approvals Management (AME) and Oracle Workflow.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('AME_GL_APP_GR_MEM'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: GL_AME_AG');



debug('begin add_signature: AME_GL_RULES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8684',
      p_sig_id                 => 'AME_GL_RULES',
      p_sig_sql                => 'SELECT ARV.Rule_id "##$$FK3$$##",
  ARV.Rule_id,
  ARV.Description Rule_Name,
  ARV.Item_Class_ID,
  --ICV.USER_ITEM_CLASS_NAME,
  ICV.NAME,
  ARV.Rule_Type                                                                                                                                                                                                      AS Rule_Type_Id,
  DECODE(ARV.Rule_type, 0, ''Combination'', 1, ''List Creation'', 2, ''List Creation Exception'', 3, ''List Modification'', 4, ''Substitution'', 5, ''Pre List Approver Group'', 6, ''Post List Approver Group'', 7, ''Production'') AS Rule_Type_Meaning,
  TO_CHAR(ARV.Start_Date, ''DD-MM-YYYY'')                                                                                                                                                                              AS Start_date,
  TO_CHAR(ARV.End_Date,''DD-MM-YYYY'')                                                                                                                                                                                 AS End_Date,
  ARU.item_id                                                                                                                                                                                                        AS Application_id,
  DECODE(ARU.Approver_Category, ''A'', ''Approver'', ''F'', ''For Your Information'')                                                                                                                                        AS Category ,
  ARU.Priority,
  FU.User_Name                             AS Created_By,
  TO_CHAR(ARV.Creation_Date, ''DD_MM-YYYY'') AS Creation_Date
FROM AME_Rules ARV,
  AME_Rule_Usages ARU,
  ame_item_classes ICV,
  FND_User FU
WHERE ARV.Item_Class_Id = ICV.Item_Class_Id
AND ARV.Created_By      = FU.User_id
AND ARV.Rule_Id         = ARU.Rule_Id
AND ARU.Item_Id         = (SELECT application_Id FROM ame_Calling_Apps WHERE fnd_Application_Id = 101)
AND sysdate BETWEEN ICV.start_date AND NVL(ICV.end_date -(1/84600),sysdate)
AND sysdate BETWEEN ARV.start_date AND NVL(ARV.end_date -(1/84600),sysdate)
AND sysdate BETWEEN ARU.start_date AND NVL(ARU.end_date -(1/84600),sysdate)',
