debug('begin add_signature: AME_GL_HIER');
   l_info('##MASK##EMPLOYEE_NAME'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##PERSON_ID'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##SUPERVISOR_ID'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##SUPERVISOR_NAME'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9735',
      p_sig_id                 => 'AME_GL_HIER',
      p_sig_sql                => 'SELECT LEVEL,
  a.*
FROM
  (SELECT a.person_id Person_id,
    a.full_name employee_name,
    (SELECT AUTHORIZATION_LIMIT
    FROM gl_authorization_limits
    WHERE ledger_id = ##$$LEDGID$$##
    AND employee_id = a.person_id
    ) auth_limit,
    supervisor_id,
    c.full_name supervisor_name,
    (SELECT AUTHORIZATION_LIMIT
    FROM gl_authorization_limits
    WHERE ledger_id = ##$$LEDGID$$##
    AND employee_id = c.person_id
    ) SUp_Auth_Limit
  FROM per_people_f a,
    per_assignments_f b,
    per_people_f c
  WHERE 1                  = 1
  AND a.effective_end_date > SYSDATE
  AND c.effective_end_date > SYSDATE
  AND a.person_id          = b.person_id
  AND b.effective_end_date > SYSDATE
  AND c.person_id          = b.supervisor_id
  )a
  START WITH Person_id =
  (SELECT NUMBER_VALUE
  FROM wf_item_Attribute_values wias,
    gl_Je_Batches gjb
  WHERE wias.item_type = ''GLBATCH''
  AND wias.item_key LIKE TO_CHAR(gjb.Je_batch_id)
    ||''%''
  AND gjb.je_Batch_Id = ##$$JE_BATCH_ID$$##
  AND NUMBER_VALUE is not null
  AND wias.name       = ''PREPARER_ID''
  )
  CONNECT BY NOCYCLE PRIOR supervisor_name = employee_name
ORDER BY 1',
      p_title                  => 'Supervisor Hierarchy',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'User should have the Authorization limits to approve any batch if supervisory hierarchy is triggered.<br>
This sections gives the details of the authorization limits set for the entire hierarchy for the preparer of the journal batch.<br>',
      p_solution               => 'Please set the sufficient Authorization Limits for the supervisor who has to approve journal batch.<br>
Following note helps in approval setup and troubleshooting:<br>
[176459.1] R12: How to Setup, Use and Troubleshoot General Ledger Journal Approval Workflow',
      p_success_msg            => 'User should have the Authorization limits to approve any batch if supervisory hierarchy is triggered.<br>
This sections gives the details of the authorization limits set for the entire hierarchy for the preparer of the journal batch.<br>

Please set the sufficient Authorization Limits for the supervisor who has to approve journal batch.<br>
Following note helps in approval setup and troubleshooting:<br>
[176459.1] R12: How to Setup, Use and Troubleshoot General Ledger Journal Approval Workflow',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: AME_GL_HIER');



