debug('begin add_signature: GL_AME_WFSTAT_AS');
   l_info('##MASK##PERFORMED_BY'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8768',
      p_sig_id                 => 'GL_AME_WFSTAT_AS',
      p_sig_sql                => 'SELECT TO_CHAR(ias.begin_date,''DD-MON-RR HH24:MI:SS'') begin_date,
  TO_CHAR(ias.end_date,''DD-MON-RR HH24:MI:SS'') end_date,
  ap.name
  ||''/''
  ||pa.instance_label Activity,
  ias.activity_status Status,
  ias.activity_result_code Result,
  ias.assigned_user assigned_user,
  ias.notification_id NID,
  ntf.status Status,
  ias.action,
  ias.performed_by
FROM wf_item_activity_statuses ias,
  wf_process_activities pa,
  wf_activities ac,
  wf_activities ap,
  wf_items i,
  wf_notifications ntf
WHERE ias.item_type        = ''##$$FK1$$##''
AND ias.item_key           = ''##$$FK2$$##''
AND ias.process_activity   = pa.instance_id
AND pa.activity_name       = ac.name
AND pa.activity_item_type  = ac.item_type
AND pa.process_name        = ap.name
AND pa.process_item_type   = ap.item_type
AND pa.process_version     = ap.version
AND i.item_type            = ias.item_type 
AND i.item_key             = ias.item_key
AND i.begin_date          >= ac.begin_date
AND i.begin_date           < NVL(ac.end_date, i.begin_date+1)
AND ntf.notification_id(+) = ias.notification_id
ORDER BY ias.begin_date,
  ias.execution_time',
      p_title                  => 'WFSTAT - Activity Statuses',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This is the output for WFSTAT - Activity Statuses.
',
