',
      p_success_msg            => 'This is the output for WFSTAT - Activity Statuses. <br>
WF Activity Statuses must exist for Journal approval.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
