debug('begin add_signature: GL_AME_WFSTAT - ITEM_ATT_VAL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8775',
      p_sig_id                 => 'GL_AME_WFSTAT - ITEM_ATT_VAL',
      p_sig_sql                => 'SELECT wiav.name attr_name,
  wia.type value_type,
CASE 
           WHEN wiav.name in (''#FROM_ROLE'',
''#SCHEMA'',
''AME_ADMIN_USER'',
''CONTACT'',
''INITIATOR_NAME'',
''RECIPIENT_NAME'',
''UI_ACTION_USER_ID'',
''UI_ACTION_USER_NAME'') THEN
               SUBSTR(wiav.text_value, 1, LENGTH(wiav.text_value) * 3 / 4) || 
               LPAD(''*'', LENGTH(wiav.text_value) / 4, ''*'')
           ELSE 
               nvl(wiav.text_value, nvl(to_char(wiav.number_value), to_char(wiav.date_value,''DD-MON-YYYY hh24:mi:ss'')))
       END AS value 
FROM wf_item_attribute_values wiav,
  wf_item_attributes wia
WHERE wiav.item_type = ''##$$FK1$$##''
AND wiav.item_key    = ''##$$FK2$$##''
AND wia.item_type(+) = wiav.item_type
AND wia.name(+)      = wiav.name
AND wia.type(+)     <> ''EVENT''',
      p_title                  => 'WFSTAT - Item Attribute Values',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This section retrieves all values for item attributes.
',
      p_solution               => '',
      p_success_msg            => 'This section retrieves all values for item attributes.

',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: GL_AME_WFSTAT - ITEM_ATT_VAL');



