debug('begin add_signature: GL_FAH_CAL_PERIOD_NAMES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10276',
      p_sig_id                 => 'GL_FAH_CAL_PERIOD_NAMES',
      p_sig_sql                => 'SELECT prd.period_name,
  prd.period_year,
  prd.period_num
FROM gl_periods prd,
  gl_ledgers lgr
WHERE lgr.ledger_id     = ##$$LEDGID$$##
AND prd.period_set_name = lgr.period_set_name
AND prd.period_type     = lgr.accounted_period_type
AND (prd.period_name LIKE '' %''
OR prd.period_name LIKE ''% ''
OR prd.period_name LIKE ''%"%''
OR prd.period_name LIKE ''%[%''
OR prd.period_name LIKE ''%]%''
OR prd.period_name LIKE ''% %''
OR prd.period_name LIKE ''% %''
OR prd.period_name LIKE ''%''
  ||Chr(9)
  ||''%''
OR prd.period_name LIKE ''@%''
OR prd.period_name LIKE ''\%''
OR prd.period_name LIKE ''{%''
OR prd.period_name LIKE ''}%''
OR prd.period_name LIKE '',%''
OR prd.period_name LIKE ''-%''
OR prd.period_name LIKE ''=%''
OR prd.period_name LIKE ''<%''
OR prd.period_name LIKE ''(%''
OR prd.period_name LIKE '')%''
OR prd.period_name LIKE ''.%''
OR prd.period_name LIKE ''+%''
OR prd.period_name LIKE ''''''%''
OR prd.period_name LIKE ''|%''
OR Prd.Period_Name LIKE ''\_%'' ESCAPE ''\'')
ORDER BY period_year,
  period_num',
      p_title                  => 'Special Characters in Period Names',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Special characters in period names are not allowed for Fusion Accounting Hub transfer.',
      p_solution               => 'Please do not change the period names. Log SR with product Oracle General Ledger.',
      p_success_msg            => 'No special characters identified in Period Names.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: GL_FAH_CAL_PERIOD_NAMES');



