debug('begin add_signature: GL_FAH_SEG_VAL_DES_SPL_CHAR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10273',
      p_sig_id                 => 'GL_FAH_SEG_VAL_DES_SPL_CHAR',
      p_sig_sql                => 'SELECT lgr.name ledger_name,
  fvs.flex_value_set_name,
  val.flex_value,
  val.description,
  ''Leading Space detected''
FROM gl_ledgers lgr,
  fnd_id_flex_segments flex_seg,
  fnd_flex_value_sets fvs,
  fnd_flex_values_vl val
WHERE  lgr.ledger_id = ##$$LEDGID$$##
AND lgr.chart_of_accounts_id = flex_seg.id_flex_num
AND flex_seg.application_id    = 101
AND flex_seg.id_flex_code      = ''GL#''
AND flex_seg.flex_value_set_id = fvs.flex_value_set_id
AND fvs.flex_value_set_id      = val.flex_value_set_id
AND val.description LIKE '' %''
UNION
SELECT lgr.name ledger_name,
  fvs.flex_value_set_name,
  val.flex_value,
  val.description,
  ''Trailing Space detected''
FROM gl_ledgers lgr,
  fnd_id_flex_segments flex_seg,
  fnd_flex_value_sets fvs,
  fnd_flex_values_vl val
WHERE  lgr.ledger_id = ##$$LEDGID$$##
AND lgr.chart_of_accounts_id = flex_seg.id_flex_num
AND flex_seg.application_id    = 101
AND flex_seg.id_flex_code      = ''GL#''
AND flex_seg.flex_value_set_id = fvs.flex_value_set_id
AND fvs.flex_value_set_id      = val.flex_value_set_id
AND val.description LIKE ''% ''
UNION
SELECT lgr.name ledger_name,
  fvs.flex_value_set_name,
  val.flex_value,
  val.description,
  ''Contains a CHARACTER NOT Allowed''
FROM gl_ledgers lgr,
  fnd_id_flex_segments flex_seg,
  fnd_flex_value_sets fvs,
  fnd_flex_values_vl val
WHERE lgr.ledger_id = ##$$LEDGID$$##
AND lgr.chart_of_accounts_id = flex_seg.id_flex_num
AND flex_seg.application_id    = 101
AND flex_seg.id_flex_code      = ''GL#''
AND flex_seg.flex_value_set_id = fvs.flex_value_set_id
AND fvs.flex_value_set_id      = val.flex_value_set_id
AND ( val.description LIKE ''%"%''
OR val.description LIKE ''%[%''
OR val.description LIKE ''%]%'')
UNION
SELECT lgr.name ledger_name,
  fvs.flex_value_set_name,
  val.flex_value,
  val.description,
  ''New Line CHARACTER detected''
FROM gl_ledgers lgr,
  fnd_id_flex_segments flex_seg,
  fnd_flex_value_sets fvs,
  fnd_flex_values_vl val
WHERE lgr.ledger_id = ##$$LEDGID$$##
AND lgr.chart_of_accounts_id = flex_seg.id_flex_num
AND flex_seg.application_id    = 101
AND flex_seg.id_flex_code      = ''GL#''
AND flex_seg.flex_value_set_id = fvs.flex_value_set_id
AND fvs.flex_value_set_id      = val.flex_value_set_id
AND val.description LIKE ''%''||Chr(9)||''%''',
      p_title                  => 'Special Characters in Segment Value Descriptions',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Special Characters are not allowed in segment value description for Fusion Accounting Hub transfer.',
      p_solution               => '1) Log into General ledger Responsibility<br>
2) Navigate to Setup-Financials-Flexfields-Key-Values<br>
3) Query the values returned by the query<br>
4) Remove the special characters/Leading space/Trailing spaces<br>
5) Save and compile the values.',
      p_success_msg            => 'No special characters identified in Segment Value Descriptions.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: GL_FAH_SEG_VAL_DES_SPL_CHAR');



