debug('begin add_signature: CONSOLIDATION_DEFINITION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13760',
      p_sig_id                 => 'CONSOLIDATION_DEFINITION',
      p_sig_sql                => 'SELECT distinct cons.consolidation_id consolidation_id
  , cons.name "Name"
--  , cons.description "Description"
  , decode(cons.security_flag,  ''N'', ''No'', ''Y'', ''Yes'', cons.security_flag) "Consolidation Enable Security"
   , cons.to_ledger_id "Parent Ledger ID" 
  , ledger2.name "Parent"
  , cons.from_ledger_id "Subsidary Ledger ID"
  , gl_fc_xlate_pkg.get_ledger_name(ledger1.name, ledger1.ledger_id, cons.from_currency_code) "Subsidary"
  , decode(cons.method, ''B'', ''Balances'', ''T'', ''Transactions'', cons.method) "Method"
     , cons.from_currency_code "Currency"
     , decode( cons.usage_code, ''S'', ''Standard'', ''B'', ''Standard and Average'', ''A'', ''Average'', cons.usage_code) "Usage"
     , decode( cons.run_journal_import_flag, ''N'', ''No'', ''Y'', ''Yes'', cons.run_journal_import_flag) "Run Journal Import Flag"
     , decode( cons.summarize_lines_flag, ''N'', ''No'', ''Y'', ''Yes'', cons.summarize_lines_flag) "Create Summary Journals"
     , decode( cons.audit_mode_flag, ''N'', ''No'', ''Y'', ''Yes'', cons.audit_mode_flag) "Audit Mode"
     , decode( nvl(cons.run_posting_flag,''N''), ''N'', ''No'', ''Y'', ''Yes'', nvl(cons.run_posting_flag,''N'')) "Auto Post"
     , map.coa_mapping_id "##$$FK1$$##"
     , map.coa_mapping_id 
     ,map.name "Mapping"
     , decode(map.security_flag,  ''N'', ''No'', ''Y'', ''Yes'', map.security_flag) "COA Mapping Enable Security "
     , fifst.id_flex_structure_name ||'' (''||fifst.id_flex_num||'')'' "Source COA/ID"
     , fifst1.id_flex_structure_name ||'' (''||fifst1.id_flex_num||'')'' "Target COA/ID" 
     ,to_char(map.start_date_active, ''DD-MON-YYYY'') "Mapping Start Date"
      ,to_char(map.end_date_active, ''DD-MON-YYYY'') "Mapping End Date"
 FROM gl_ledgers ledger1, 
 gl_ledgers ledger2, 
 gl_consolidation cons, 
 gl_coa_mappings map , 
 fnd_id_flex_structures_tl fifst , 
 fnd_id_flex_structures_tl fifst1
 WHERE cons.from_ledger_id = ledger1.ledger_id 
 AND cons.to_ledger_id = ledger2.ledger_id 
 AND cons.coa_mapping_id = map.coa_mapping_id 
 AND  map.from_coa_id = fifst.id_flex_num
 AND  map.to_coa_id = fifst1.id_flex_num 
-- AND cons.to_ledger_id = ##$$LEDGID$$##
 AND cons.consolidation_id = ##$$CONSOLIDATIONID$$##
 AND fifst.id_flex_code = ''GL#'' 
 AND fifst.application_id = 101
 AND fifst1.id_flex_code = ''GL#'' 
 AND fifst1.application_id = 101',
      p_title                  => 'Consolidation Definition and COA Mapping',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Consolidation Definition Setup and it''s Chart of Accounts Mapping details for the selected Consolidation ID/Name.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('CONSOLIDATION_COA_SEGMENT_RULES','CONSOLIDATION_COA_ACCOUNT_RULES'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '18'
      );
   l_info.delete;
debug('end add_signature: CONSOLIDATION_DEFINITION');



