PROCEDURE main(
            p_ledger_id                    IN NUMBER      DEFAULT NULL
           ,p_period_name                  IN VARCHAR2    DEFAULT NULL
           ,p_bud_ver_id                   IN NUMBER      DEFAULT NULL
           ,p_dc                           IN VARCHAR2    DEFAULT 'Y'
           ,p_batch_id                     IN NUMBER      DEFAULT NULL
           ,p_rec_batch_id                 IN NUMBER      DEFAULT NULL
           ,p_ccid                         IN NUMBER      DEFAULT NULL
           ,p_rep_id                       IN NUMBER      DEFAULT NULL
           ,p_consolidation_id             IN NUMBER      DEFAULT NULL
           ,p_max_output_rows              IN NUMBER      DEFAULT 100
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';



  l_step := '10';
  initialize_files;

  analyzer_title := 'General Ledger Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_ledger_id                    => p_ledger_id
    ,p_period_name                  => p_period_name
    ,p_bud_ver_id                   => p_bud_ver_id
    ,p_dc                           => upper(p_dc)
    ,p_batch_id                     => p_batch_id
    ,p_rec_batch_id                 => p_rec_batch_id
    ,p_ccid                         => p_ccid
    ,p_rep_id                       => p_rep_id
    ,p_consolidation_id             => p_consolidation_id
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: Instance_Overview');
